function unstakeLocked(uint256 _stakeId) external nonReentrant {
        require(_stakeId < lockedStakes[msg.sender].length, "Invalid stake ID");
        LockedStake storage lockedStake = lockedStakes[msg.sender][_stakeId];

        require(!lockedStake.withdrawn, "Stake already withdrawn");
        require(lockedStake.sharesAmount > 0, "Stake amount is zero");

        // Update reward pool
        updateRewardPool();

        // Check if early withdrawal
        bool isEarlyWithdrawal = (block.timestamp < lockedStake.lockEndTime);

        // Calculate penalty (if early withdrawal)
        uint256 penalty = 0;
        uint256 sharesToBurn = lockedStake.sharesAmount;
        // uint256 hskToReturn = getHSKForShares(sharesToBurn);
        uint256 hskToReturn = getHSKForSharesByDuration(sharesToBurn, lockedStake.lockDuration);
        uint256 maxStakeReward = getStakeRecordMaxReward(lockedStake);
        // 原始质押金额
        uint256 originalAmount = lockedStake.hskAmount; 
        // 不能超过最大收益
        if (hskToReturn > maxStakeReward + originalAmount) {
             hskToReturn = maxStakeReward + originalAmount;
        }

        // 确定质押类型并更新该类型的质押总量
        StakeType stakeType;
        if (lockedStake.lockDuration == 30 days)
            stakeType = StakeType.FIXED_30_DAYS;
        else if (lockedStake.lockDuration == 90 days)
            stakeType = StakeType.FIXED_90_DAYS;
        else if (lockedStake.lockDuration == 180 days)
            stakeType = StakeType.FIXED_180_DAYS;
        else if (lockedStake.lockDuration == 365 days)
            stakeType = StakeType.FIXED_365_DAYS;
        else stakeType = StakeType.FLEXIBLE;

        // 更新该锁定期类型的质押总量
        totalSharesByStakeType[stakeType] -= sharesToBurn;

        if (isEarlyWithdrawal) {
            // 直接按照比例全扣， 不需要计算 !!!
            penalty =
                (hskToReturn * earlyWithdrawalPenalty[stakeType]) /
                BASIS_POINTS;

            hskToReturn -= penalty;

            // Add penalty to reserved rewards
            reservedRewards += penalty;
        }

        // Mark stake as withdrawn
        lockedStake.withdrawn = true;

        // 计算原始质押金额和奖励部分烦烦烦方法
        uint256 originalStake = lockedStake.hskAmount;
        uint256 rewardPart = 0;

        // 如果返还金额大于原始质押金额，则差额为奖励部分
        if (hskToReturn > originalStake) {
            rewardPart = hskToReturn - originalStake;
        } else {
            // 如果返还金额小于原始质押金额（可能是因为提前提取的罚金），则全部视为原始质押
            originalStake = hskToReturn;
        }

        totalPooledHSK = totalPooledHSK - hskToReturn - penalty;

        // 如果有奖励部分，从已支付奖励中减去
        if (rewardPart > 0) {
            // 确保不会减去超过已支付奖励的金额
            if (rewardPart > totalPaidRewards) {
                rewardPart = totalPaidRewards;
            }
            totalPaidRewards -= rewardPart;
            totalPooledHSK -= rewardPart;
        }

        // Check if user has enough stHSK
        require(
            stHSK.balanceOf(msg.sender) >= sharesToBurn,
            "Insufficient stHSK balance"
        );

        // Burn stHSK tokens
        stHSK.burn(msg.sender, sharesToBurn);

        // Return HSK tokens
        bool transferSuccess = safeHskTransfer(
            payable(msg.sender),
            hskToReturn
        );
        require(transferSuccess, "HSK transfer failed");


        emit Unstake(
            msg.sender,
            sharesToBurn,
            hskToReturn,
            isEarlyWithdrawal,
            penalty,
            _stakeId
        );
    }

function updateRewardPool() public {
        if (block.number <= lastRewardBlock) {
            return;
        }

        if (totalPooledHSK == 0) {
            lastRewardBlock = block.number;
            return;
        }

        uint256 multiplier = block.number - lastRewardBlock;
        uint256 hskReward = multiplier * hskPerBlock;

        // Calculate and limit APR using configurable block time
        // SECONDS_PER_YEAR is 365 days (31,536,000 seconds)
        // Explicitly calculate blocks per year based on the configured block time
        uint256 blocksPerYear = SECONDS_PER_YEAR / blockTime;  // 31,536,000 / blockTime
        uint256 annualReward = hskPerBlock * blocksPerYear;
        uint256 currentAPR = (annualReward * BASIS_POINTS) / totalPooledHSK;
        if (currentAPR > MAX_APR) {
            hskReward = (totalPooledHSK * MAX_APR * multiplier) / (BASIS_POINTS * blocksPerYear);
        }

        // 计算额外的锁定期奖励
        uint256 additionalBonusRewards = 0;

        // 获取总shares数量
        uint256 totalShares = stHSK.totalSupply();

        if (totalShares > 0) {
            // 计算每种锁定期类型的额外奖励
            uint256 bonusReward30Days = 0;
            uint256 bonusReward90Days = 0;
            uint256 bonusReward180Days = 0;
            uint256 bonusReward365Days = 0;
            // 只有当该类型有质押时才计算奖励
            if (totalSharesByStakeType[StakeType.FIXED_30_DAYS] > 0) {
                // 计算该类型质押占总质押的比例
                uint256 shareRatio30Days = (totalSharesByStakeType[StakeType.FIXED_30_DAYS] * PRECISION_FACTOR) / totalShares;
                // 计算该类型的基础奖励
                uint256 baseReward30Days = (hskReward * shareRatio30Days) / PRECISION_FACTOR;
                // 计算该类型的额外奖励
                bonusReward30Days = (baseReward30Days * stakingBonus[StakeType.FIXED_30_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_90_DAYS] > 0) {
                uint256 shareRatio90Days = (totalSharesByStakeType[StakeType.FIXED_90_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward90Days = (hskReward * shareRatio90Days) / PRECISION_FACTOR;
                bonusReward90Days = (baseReward90Days * stakingBonus[StakeType.FIXED_90_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_180_DAYS] > 0) {
                uint256 shareRatio180Days = (totalSharesByStakeType[StakeType.FIXED_180_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward180Days = (hskReward * shareRatio180Days) / PRECISION_FACTOR;
                bonusReward180Days = (baseReward180Days * stakingBonus[StakeType.FIXED_180_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_365_DAYS] > 0) {
                uint256 shareRatio365Days = (totalSharesByStakeType[StakeType.FIXED_365_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward365Days = (hskReward * shareRatio365Days) / PRECISION_FACTOR;
                bonusReward365Days = (baseReward365Days * stakingBonus[StakeType.FIXED_365_DAYS]) / BASIS_POINTS;
            }
            // bonusRewardFlexible 不计算 直接为0
            // 计算总的额外奖励
            additionalBonusRewards = bonusReward30Days + bonusReward90Days + bonusReward180Days + bonusReward365Days;
        }

        // 总奖励 = 基础奖励 + 额外的锁定期奖励
        uint256 totalReward = hskReward + additionalBonusRewards;

        // 检查合约是否有足够的奖励资金
        // 使用annualRewardsBudget来计算可用奖励，而不是依赖实际合约余额
        // !!! 这里需要修改  不需要检查，定期打钱进去
        uint256 availableRewards = reservedRewards;

        if (availableRewards >= totalReward) {
            totalPooledHSK += totalReward;
            reservedRewards -= totalReward;

            // 更新已支付的奖励总量
            totalPaidRewards += totalReward;
            // Update exchange rate
            emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
        } else {
            if (availableRewards > 0) {
                totalPooledHSK += availableRewards;

                // 更新已支付的奖励总量
                totalPaidRewards += availableRewards;

                totalReward = availableRewards;
                reservedRewards = 0;

                // Update exchange rate
                emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
            }
            emit InsufficientRewards(totalReward, reservedRewards);
        }

        lastRewardBlock = block.number;
    }

function getHSKForShares(uint256 _sharesAmount) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        uint256 totalRewards = hskPerBlock * (block.number - startBlock);
        uint256 unClaimedRewards = totalRewards - totalPaidRewards;

        return (_sharesAmount * totalPooledHSK + unClaimedRewards) / totalShares;
    }

function getHSKForSharesByDuration(uint256 _sharesAmount, uint256 _lockDuration) public view returns (uint256) {
        StakeType stakeType;

        if (_lockDuration == 0) {
            stakeType = StakeType.FLEXIBLE;
        } else if (_lockDuration <= 30 days) {
            stakeType = StakeType.FIXED_30_DAYS;
        } else if (_lockDuration <= 90 days) {
            stakeType = StakeType.FIXED_90_DAYS;
        } else if (_lockDuration <= 180 days) {
            stakeType = StakeType.FIXED_180_DAYS;
        } else {
            stakeType = StakeType.FIXED_365_DAYS;
        }

        return getHSKForSharesByType(_sharesAmount, stakeType);
    }

function getStakeRecordMaxReward(LockedStake memory userStake) internal view returns (uint256) {
        // Early return for zero values
        if (userStake.sharesAmount == 0 || userStake.hskAmount == 0) {
            return 0;
        }

        StakeType stakeType;
        if (userStake.lockDuration == 30 days)
            stakeType = StakeType.FIXED_30_DAYS;
        else if (userStake.lockDuration == 90 days)
            stakeType = StakeType.FIXED_90_DAYS;
        else if (userStake.lockDuration == 180 days)
            stakeType = StakeType.FIXED_180_DAYS;
        else if (userStake.lockDuration == 365 days)
            stakeType = StakeType.FIXED_365_DAYS;
        else stakeType = StakeType.FLEXIBLE;

        // 计算锁定开始时间
        uint256 lockStartTime = userStake.lockEndTime - userStake.lockDuration;

        uint256 elapsedTime = block.timestamp - lockStartTime; // 正常计算已经过的时间
        uint256 completionYearRatio = elapsedTime * BASIS_POINTS / SECONDS_PER_YEAR;

        // 根据已完成比例调整APR
        uint256 adjustedAPR = (maxAPRs[stakeType] * completionYearRatio) / BASIS_POINTS;
        uint256 maxReward = (userStake.hskAmount * adjustedAPR) / BASIS_POINTS;

        return maxReward;
    }

function balanceOf(address account) public view virtual override returns (uint256) {
        return _balances[account];
    }

function burn(address from, uint256 sharesAmount) external onlyOwner {
        _burn(from, sharesAmount);
    }

function safeHskTransfer(address payable _to, uint256 _amount) internal returns (bool) {
        // 只检查合约总余额是否足够
        require(address(this).balance >= _amount, "Insufficient contract balance");

        // 发送资金
        (bool success, ) = _to.call{value: _amount}("");
        require(success, "HSK transfer failed");
        return true;
    }

function totalSupply() public view virtual override returns (uint256) {
        return _totalSupply;
    }

function getHSKForSharesByType(uint256 _sharesAmount, StakeType stakeType) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        if (totalSharesByStakeType[stakeType] == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        uint256 totalRewards = hskPerBlock * (block.number - startBlock);
        uint256 unClaimedRewards = totalRewards - totalPaidRewards;

        uint256 ratio = calculateCorrectionFactor(stakeType);
        //  reward 不能超 最大 APR
        uint256 reward = _sharesAmount * unClaimedRewards * ratio / (totalSharesByStakeType[stakeType] * BASIS_POINTS);
        uint256 base =  (_sharesAmount * totalPooledHSK) / totalShares;
        uint256 maxReward = _sharesAmount * maxAPRs[stakeType] / BASIS_POINTS;
        if (reward > maxReward) {
            reward = maxReward;
        }
        return reward + base;
    }

function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        uint256 accountBalance = _balances[account];
        require(accountBalance >= amount, "ERC20: burn amount exceeds balance");
        unchecked {
            _balances[account] = accountBalance - amount;
            // Overflow not possible: amount <= accountBalance <= totalSupply.
            _totalSupply -= amount;
        }

        emit Transfer(account, address(0), amount);

        _afterTokenTransfer(account, address(0), amount);
    }

function calculateCorrectionFactor(StakeType stakeType) public view returns (uint256) {
        // 计算所有池的总加权质押量
        uint256 totalWeightedShares = 0;
        for (uint256 i = 0; i < 5; i++) {
            StakeType currentType = StakeType(i);
            totalWeightedShares += maxAPRs[currentType] * totalSharesByStakeType[currentType];
        }
        // 避免除以零
        if (totalWeightedShares == 0) {
            return 1;
        }

        // 计算指定池的加权质押量
        uint256 weightedShares = maxAPRs[stakeType] * totalSharesByStakeType[stakeType];

        // 计算占总质押的百分比
        uint256 percentOfTotalShares = totalSharesByStakeType[stakeType] * BASIS_POINTS / totalWeightedShares;

        // 如果百分比为0，避免除以零
        if (percentOfTotalShares == 0) {
            return (weightedShares * BASIS_POINTS) / totalWeightedShares;
        }

        return (weightedShares * BASIS_POINTS) / totalWeightedShares;
    }

function deposit() public payable {
        _mint(msg.sender, msg.value);
        emit Deposit(msg.sender, msg.value);
    }

function _mint(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: mint to the zero address");

        _beforeTokenTransfer(address(0), account, amount);

        _totalSupply += amount;
        unchecked {
            // Overflow not possible: balance + amount is at most totalSupply + amount, which is checked above.
            _balances[account] += amount;
        }
        emit Transfer(address(0), account, amount);

        _afterTokenTransfer(address(0), account, amount);
    }

function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual {}

function _afterTokenTransfer(address from, address to, uint256 amount) internal virtual {}

function acceptOffer(uint256 offerId)
        external
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer == msg.sender) revert CannotAcceptOwnOffer();
        if (block.timestamp >= offer.expirationTime)
            revert OfferExpired(offerId, offer.expirationTime);

        IERC1155AsteroidX token = asteroidXToken;
        if (token.balanceOf(msg.sender, offer.tokenId) < offer.amount)
            revert InsufficientTokenBalance(offer.tokenId, offer.amount);

        uint256 totalOfferValue = offer.amount * offer.pricePerToken;
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalOfferValue,
            offer.paymentToken
        );

        _transferNFT(
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            true
        );
        _handleOfferFundWithdrawal(
            offerId,
            offer.paymentToken,
            msg.sender,
            feeRecipient,
            sellerProceeds,
            platformFee
        );
        _deactivateOffer(offerId);
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER,
            msg.sender,
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferAccepted(
            offerId,
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            totalOfferValue,
            block.timestamp,
            offer.paymentToken
        );
    }

function _calculateFees(uint256 totalAmount, address paymentToken)
        internal
        view
        returns (uint256 platformFee, uint256 sellerProceeds)
    {
        uint256 feeRateToUse = paymentTokenFeeRates[paymentToken];
        platformFee = (feeRateToUse > 0 && totalAmount > 0)
            ? Math.mulDiv(totalAmount, feeRateToUse, 10000)
            : 0;
        sellerProceeds = totalAmount - platformFee;
        return (platformFee, sellerProceeds);
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                address(marketplaceVaultContract),
                tokenId,
                amount,
                ""
            );
            marketplaceVaultContract.transferNFTToBuyer(
                address(asteroidXToken),
                tokenId,
                amount,
                to
            );
        } else {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                to,
                tokenId,
                amount,
                ""
            );
        }
    }

function _handleOfferFundWithdrawal(
        uint256 offerId,
        address paymentToken,
        address seller,
        address feeRecipientAddress,
        uint256 sellerProceeds,
        uint256 platformFee
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.withdrawOfferFundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee
            );
        } else {
            marketplaceVaultContract.withdrawOfferERC20FundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee,
                paymentToken
            );
        }
    }

function _deactivateOffer(uint256 offerId) internal {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) return;
        offer.active = false;
        activeOffersByToken[offer.tokenId].remove(offerId);
        activeOffersByBuyer[offer.buyer].remove(offerId);
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

function mulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 result) {
        unchecked {
            (uint256 high, uint256 low) = mul512(x, y);

            // Handle non-overflow cases, 256 by 256 division.
            if (high == 0) {
                // Solidity will revert if denominator == 0, unlike the div opcode on its own.
                // The surrounding unchecked block does not change this fact.
                // See https://docs.soliditylang.org/en/latest/control-structures.html#checked-or-unchecked-arithmetic.
                return low / denominator;
            }

            // Make sure the result is less than 2²⁵⁶. Also prevents denominator == 0.
            if (denominator <= high) {
                Panic.panic(ternary(denominator == 0, Panic.DIVISION_BY_ZERO, Panic.UNDER_OVERFLOW));
            }

            ///////////////////////////////////////////////
            // 512 by 256 division.
            ///////////////////////////////////////////////

            // Make division exact by subtracting the remainder from [high low].
            uint256 remainder;
            assembly ("memory-safe") {
                // Compute remainder using mulmod.
                remainder := mulmod(x, y, denominator)

                // Subtract 256 bit number from 512 bit number.
                high := sub(high, gt(remainder, low))
                low := sub(low, remainder)
            }

            // Factor powers of two out of denominator and compute largest power of two divisor of denominator.
            // Always >= 1. See https://cs.stackexchange.com/q/138556/92363.

            uint256 twos = denominator & (0 - denominator);
            assembly ("memory-safe") {
                // Divide denominator by twos.
                denominator := div(denominator, twos)

                // Divide [high low] by twos.
                low := div(low, twos)

                // Flip twos such that it is 2²⁵⁶ / twos. If twos is zero, then it becomes one.
                twos := add(div(sub(0, twos), twos), 1)
            }

            // Shift in bits from high into low.
            low |= high * twos;

            // Invert denominator mod 2²⁵⁶. Now that denominator is an odd number, it has an inverse modulo 2²⁵⁶ such
            // that denominator * inv ≡ 1 mod 2²⁵⁶. Compute the inverse by starting with a seed that is correct for
            // four bits. That is, denominator * inv ≡ 1 mod 2⁴.
            uint256 inverse = (3 * denominator) ^ 2;

            // Use the Newton-Raphson iteration to improve the precision. Thanks to Hensel's lifting lemma, this also
            // works in modular arithmetic, doubling the correct bits in each step.
            inverse *= 2 - denominator * inverse; // inverse mod 2⁸
            inverse *= 2 - denominator * inverse; // inverse mod 2¹⁶
            inverse *= 2 - denominator * inverse; // inverse mod 2³²
            inverse *= 2 - denominator * inverse; // inverse mod 2⁶⁴
            inverse *= 2 - denominator * inverse; // inverse mod 2¹²⁸
            inverse *= 2 - denominator * inverse; // inverse mod 2²⁵⁶

            // Because the division is now exact we can divide by multiplying with the modular inverse of denominator.
            // This will give us the correct result modulo 2²⁵⁶. Since the preconditions guarantee that the outcome is
            // less than 2²⁵⁶, this is the final result. We don't need to compute the high bits of the result and high
            // is no longer required.
            result = low * inverse;
            return result;
        }
    }

function mulDiv(uint256 x, uint256 y, uint256 denominator, Rounding rounding) internal pure returns (uint256) {
        return mulDiv(x, y, denominator) + SafeCast.toUint(unsignedRoundsUp(rounding) && mulmod(x, y, denominator) > 0);
    }

function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

function transferNFTToBuyer(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (buyer == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            buyer,
            tokenId,
            amount,
            ""
        );
        emit NFTTransferredToBuyer(tokenContract, tokenId, amount, buyer);
    }

function withdrawOfferFundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        uint256 totalAmount = sellerProceeds + platformFee;
        if (totalAmount > address(this).balance) revert InsufficientBalance();

        // First transfer to seller
        payable(seller).sendValue(sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            payable(platformFeeRecipient).sendValue(platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function withdrawOfferERC20FundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        // Get the ERC20 token contract
        IERC20 erc20Token = IERC20(token);

        // First transfer to seller
        erc20Token.safeTransfer(seller, sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            erc20Token.safeTransfer(platformFeeRecipient, platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function purchaseListing(uint256 listingId, uint256 amount)
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) revert ListingNotActive(listingId);
        if (block.timestamp >= listing.expirationTime)
            revert ListingExpired(listingId, listing.expirationTime);
        if (amount == 0 || amount > listing.amount)
            revert InvalidAmount(amount, listing.amount);
        if (msg.sender == listing.seller) revert CannotBuyOwnListing();

        uint256 totalPrice = amount * listing.pricePerToken;
        listing.amount -= amount;
        if (listing.amount == 0) {
            _deactivateListing(listingId);
        }
        marketplaceVaultContract.transferNFTToBuyer(
            address(asteroidXToken),
            listing.tokenId,
            amount,
            msg.sender
        );
        _handlePaymentWithFees(
            listing.paymentToken,
            msg.sender,
            listing.seller,
            totalPrice,
            msg.value,
            listing.paymentToken
        );
        _recordTransaction(
            listing.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.SALE,
            listing.seller,
            msg.sender,
            amount,
            listing.pricePerToken,
            listing.paymentToken,
            listingId
        );
        emit ListingSold(
            listingId,
            msg.sender,
            listing.tokenId,
            amount,
            totalPrice,
            block.timestamp,
            listing.paymentToken
        );
    }

function _deactivateListing(uint256 listingId) internal {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) return;
        listing.active = false;
        activeListingsByToken[listing.tokenId].remove(listingId);
        activeListingsBySeller[listing.seller].remove(listingId);
    }

