            p := sub(sar(96, mul(p, x)), 45023709667254063763336534515857)
            p := sub(sar(96, mul(p, x)), 14706773417378608786704636184526)
            p := sub(mul(p, x), shl(96, 795164235651350426258249787498))
        // We leave `p` in `2**192` basis so we don't need to scale it back up for the division.

        // `q` is monic by convention.
            let q := add(5573035233440673466300451813936, x)
            q := add(71694874799317883764090561454958, sar(96, mul(x, q)))
            q := add(283447036172924575727196451306956, sar(96, mul(x, q)))
            q := add(401686690394027663651624208769553, sar(96, mul(x, q)))
            q := add(204048457590392012362485061816622, sar(96, mul(x, q)))
            q := add(31853899698501571402653359427138, sar(96, mul(x, q)))
            q := add(909429971244387300277376558375, sar(96, mul(x, q)))

        // `p / q` is in the range `(0, 0.125) * 2**96`.

        // Finalization, we need to:
        // - Multiply by the scale factor `s = 5.549…`.
        // - Add `ln(2**96 / 10**18)`.
        // - Add `k * ln(2)`.
        // - Multiply by `10**18 / 2**96 = 5**18 >> 78`.

        // The q polynomial is known not to have zeros in the domain.
        // No scaling required because p is already `2**96` too large.
            p := sdiv(p, q)
        // Multiply by the scaling factor: `s * 5**18 * 2**96`, base is now `5**18 * 2**192`.
            p := mul(1677202110996718588342820967067443963516166, p)
        // Add `ln(2) * k * 5**18 * 2**192`.
        // forgefmt: disable-next-item
            p := add(mul(16597577552685614221487285958193947469193820559219878177908093499208371, sub(159, r)), p)
        // Add `ln(2**96 / 10**18) * 5**18 * 2**192`.
            p := add(600920179829731861736702779321621459595472258049074101567377883020018308, p)
        // Base conversion: mul `2**18 / 2**192`.
            r := sar(174, p)
        }
    }

function divWad(uint256 x, uint256 y) internal pure returns (uint256 z) {
        /// @solidity memory-safe-assembly
        assembly {
        // Equivalent to `require(y != 0 && (WAD == 0 || x <= type(uint256).max / WAD))`.
            if iszero(mul(y, iszero(mul(WAD, gt(x, div(not(0), WAD)))))) {
                mstore(0x00, 0x7c5f487d) // `DivWadFailed()`.
                revert(0x1c, 0x04)
            }
            z := div(mul(x, WAD), y)
        }
    }

function unstakeLocked(uint256 _stakeId) external nonReentrant {
        require(_stakeId < lockedStakes[msg.sender].length, "Invalid stake ID");
        LockedStake storage lockedStake = lockedStakes[msg.sender][_stakeId];

        require(!lockedStake.withdrawn, "Stake already withdrawn");
        require(lockedStake.sharesAmount > 0, "Stake amount is zero");

        // Update reward pool
        updateRewardPool();

        // Check if early withdrawal
        bool isEarlyWithdrawal = (block.timestamp < lockedStake.lockEndTime);

        // Calculate penalty (if early withdrawal)
        uint256 penalty = 0;
        uint256 sharesToBurn = lockedStake.sharesAmount;
        // uint256 hskToReturn = getHSKForShares(sharesToBurn);
        uint256 hskToReturn = getHSKForSharesByDuration(sharesToBurn, lockedStake.lockDuration);
        uint256 maxStakeReward = getStakeRecordMaxReward(lockedStake);
        // 原始质押金额
        uint256 originalAmount = lockedStake.hskAmount; 
        // 不能超过最大收益
        if (hskToReturn > maxStakeReward + originalAmount) {
             hskToReturn = maxStakeReward + originalAmount;
        }

        // 确定质押类型并更新该类型的质押总量
        StakeType stakeType;
        if (lockedStake.lockDuration == 30 days)
            stakeType = StakeType.FIXED_30_DAYS;
        else if (lockedStake.lockDuration == 90 days)
            stakeType = StakeType.FIXED_90_DAYS;
        else if (lockedStake.lockDuration == 180 days)
            stakeType = StakeType.FIXED_180_DAYS;
        else if (lockedStake.lockDuration == 365 days)
            stakeType = StakeType.FIXED_365_DAYS;
        else stakeType = StakeType.FLEXIBLE;

        // 更新该锁定期类型的质押总量
        totalSharesByStakeType[stakeType] -= sharesToBurn;

        if (isEarlyWithdrawal) {
            // 直接按照比例全扣， 不需要计算 !!!
            penalty =
                (hskToReturn * earlyWithdrawalPenalty[stakeType]) /
                BASIS_POINTS;

            hskToReturn -= penalty;

            // Add penalty to reserved rewards
            reservedRewards += penalty;
        }

        // Mark stake as withdrawn
        lockedStake.withdrawn = true;

        // 计算原始质押金额和奖励部分烦烦烦方法
        uint256 originalStake = lockedStake.hskAmount;
        uint256 rewardPart = 0;

        // 如果返还金额大于原始质押金额，则差额为奖励部分
        if (hskToReturn > originalStake) {
            rewardPart = hskToReturn - originalStake;
        } else {
            // 如果返还金额小于原始质押金额（可能是因为提前提取的罚金），则全部视为原始质押
            originalStake = hskToReturn;
        }

        totalPooledHSK = totalPooledHSK - hskToReturn - penalty;

        // 如果有奖励部分，从已支付奖励中减去
        if (rewardPart > 0) {
            // 确保不会减去超过已支付奖励的金额
            if (rewardPart > totalPaidRewards) {
                rewardPart = totalPaidRewards;
            }
            totalPaidRewards -= rewardPart;
            totalPooledHSK -= rewardPart;
        }

        // Check if user has enough stHSK
        require(
            stHSK.balanceOf(msg.sender) >= sharesToBurn,
            "Insufficient stHSK balance"
        );

        // Burn stHSK tokens
        stHSK.burn(msg.sender, sharesToBurn);

        // Return HSK tokens
        bool transferSuccess = safeHskTransfer(
            payable(msg.sender),
            hskToReturn
        );
        require(transferSuccess, "HSK transfer failed");


        emit Unstake(
            msg.sender,
            sharesToBurn,
            hskToReturn,
            isEarlyWithdrawal,
            penalty,
            _stakeId
        );
    }

function updateRewardPool() public {
        if (block.number <= lastRewardBlock) {
            return;
        }

        if (totalPooledHSK == 0) {
            lastRewardBlock = block.number;
            return;
        }

        uint256 multiplier = block.number - lastRewardBlock;
        uint256 hskReward = multiplier * hskPerBlock;

        // Calculate and limit APR using configurable block time
        // SECONDS_PER_YEAR is 365 days (31,536,000 seconds)
        // Explicitly calculate blocks per year based on the configured block time
        uint256 blocksPerYear = SECONDS_PER_YEAR / blockTime;  // 31,536,000 / blockTime
        uint256 annualReward = hskPerBlock * blocksPerYear;
        uint256 currentAPR = (annualReward * BASIS_POINTS) / totalPooledHSK;
        if (currentAPR > MAX_APR) {
            hskReward = (totalPooledHSK * MAX_APR * multiplier) / (BASIS_POINTS * blocksPerYear);
        }

        // 计算额外的锁定期奖励
        uint256 additionalBonusRewards = 0;

        // 获取总shares数量
        uint256 totalShares = stHSK.totalSupply();

        if (totalShares > 0) {
            // 计算每种锁定期类型的额外奖励
            uint256 bonusReward30Days = 0;
            uint256 bonusReward90Days = 0;
            uint256 bonusReward180Days = 0;
            uint256 bonusReward365Days = 0;
            // 只有当该类型有质押时才计算奖励
            if (totalSharesByStakeType[StakeType.FIXED_30_DAYS] > 0) {
                // 计算该类型质押占总质押的比例
                uint256 shareRatio30Days = (totalSharesByStakeType[StakeType.FIXED_30_DAYS] * PRECISION_FACTOR) / totalShares;
                // 计算该类型的基础奖励
                uint256 baseReward30Days = (hskReward * shareRatio30Days) / PRECISION_FACTOR;
                // 计算该类型的额外奖励
                bonusReward30Days = (baseReward30Days * stakingBonus[StakeType.FIXED_30_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_90_DAYS] > 0) {
                uint256 shareRatio90Days = (totalSharesByStakeType[StakeType.FIXED_90_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward90Days = (hskReward * shareRatio90Days) / PRECISION_FACTOR;
                bonusReward90Days = (baseReward90Days * stakingBonus[StakeType.FIXED_90_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_180_DAYS] > 0) {
                uint256 shareRatio180Days = (totalSharesByStakeType[StakeType.FIXED_180_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward180Days = (hskReward * shareRatio180Days) / PRECISION_FACTOR;
                bonusReward180Days = (baseReward180Days * stakingBonus[StakeType.FIXED_180_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_365_DAYS] > 0) {
                uint256 shareRatio365Days = (totalSharesByStakeType[StakeType.FIXED_365_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward365Days = (hskReward * shareRatio365Days) / PRECISION_FACTOR;
                bonusReward365Days = (baseReward365Days * stakingBonus[StakeType.FIXED_365_DAYS]) / BASIS_POINTS;
            }
            // bonusRewardFlexible 不计算 直接为0
            // 计算总的额外奖励
            additionalBonusRewards = bonusReward30Days + bonusReward90Days + bonusReward180Days + bonusReward365Days;
        }

        // 总奖励 = 基础奖励 + 额外的锁定期奖励
        uint256 totalReward = hskReward + additionalBonusRewards;

        // 检查合约是否有足够的奖励资金
        // 使用annualRewardsBudget来计算可用奖励，而不是依赖实际合约余额
        // !!! 这里需要修改  不需要检查，定期打钱进去
        uint256 availableRewards = reservedRewards;

        if (availableRewards >= totalReward) {
            totalPooledHSK += totalReward;
            reservedRewards -= totalReward;

            // 更新已支付的奖励总量
            totalPaidRewards += totalReward;
            // Update exchange rate
            emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
        } else {
            if (availableRewards > 0) {
                totalPooledHSK += availableRewards;

                // 更新已支付的奖励总量
                totalPaidRewards += availableRewards;

                totalReward = availableRewards;
                reservedRewards = 0;

                // Update exchange rate
                emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
            }
            emit InsufficientRewards(totalReward, reservedRewards);
        }

        lastRewardBlock = block.number;
    }

function getHSKForShares(uint256 _sharesAmount) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        uint256 totalRewards = hskPerBlock * (block.number - startBlock);
        uint256 unClaimedRewards = totalRewards - totalPaidRewards;

        return (_sharesAmount * totalPooledHSK + unClaimedRewards) / totalShares;
    }

function getHSKForSharesByDuration(uint256 _sharesAmount, uint256 _lockDuration) public view returns (uint256) {
        StakeType stakeType;

        if (_lockDuration == 0) {
            stakeType = StakeType.FLEXIBLE;
        } else if (_lockDuration <= 30 days) {
            stakeType = StakeType.FIXED_30_DAYS;
        } else if (_lockDuration <= 90 days) {
            stakeType = StakeType.FIXED_90_DAYS;
        } else if (_lockDuration <= 180 days) {
            stakeType = StakeType.FIXED_180_DAYS;
        } else {
            stakeType = StakeType.FIXED_365_DAYS;
        }

        return getHSKForSharesByType(_sharesAmount, stakeType);
    }

function getStakeRecordMaxReward(LockedStake memory userStake) internal view returns (uint256) {
        // Early return for zero values
        if (userStake.sharesAmount == 0 || userStake.hskAmount == 0) {
            return 0;
        }

        StakeType stakeType;
        if (userStake.lockDuration == 30 days)
            stakeType = StakeType.FIXED_30_DAYS;
        else if (userStake.lockDuration == 90 days)
            stakeType = StakeType.FIXED_90_DAYS;
        else if (userStake.lockDuration == 180 days)
            stakeType = StakeType.FIXED_180_DAYS;
        else if (userStake.lockDuration == 365 days)
            stakeType = StakeType.FIXED_365_DAYS;
        else stakeType = StakeType.FLEXIBLE;

        // 计算锁定开始时间
        uint256 lockStartTime = userStake.lockEndTime - userStake.lockDuration;

        uint256 elapsedTime = block.timestamp - lockStartTime; // 正常计算已经过的时间
        uint256 completionYearRatio = elapsedTime * BASIS_POINTS / SECONDS_PER_YEAR;

        // 根据已完成比例调整APR
        uint256 adjustedAPR = (maxAPRs[stakeType] * completionYearRatio) / BASIS_POINTS;
        uint256 maxReward = (userStake.hskAmount * adjustedAPR) / BASIS_POINTS;

        return maxReward;
    }

function balanceOf(address account) public view virtual override returns (uint256) {
        return _balances[account];
    }

function burn(address from, uint256 sharesAmount) external onlyOwner {
        _burn(from, sharesAmount);
    }

function safeHskTransfer(address payable _to, uint256 _amount) internal returns (bool) {
        // 只检查合约总余额是否足够
        require(address(this).balance >= _amount, "Insufficient contract balance");

        // 发送资金
        (bool success, ) = _to.call{value: _amount}("");
        require(success, "HSK transfer failed");
        return true;
    }

function totalSupply() public view virtual override returns (uint256) {
        return _totalSupply;
    }

function getHSKForSharesByType(uint256 _sharesAmount, StakeType stakeType) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        if (totalSharesByStakeType[stakeType] == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        uint256 totalRewards = hskPerBlock * (block.number - startBlock);
        uint256 unClaimedRewards = totalRewards - totalPaidRewards;

        uint256 ratio = calculateCorrectionFactor(stakeType);
        //  reward 不能超 最大 APR
        uint256 reward = _sharesAmount * unClaimedRewards * ratio / (totalSharesByStakeType[stakeType] * BASIS_POINTS);
        uint256 base =  (_sharesAmount * totalPooledHSK) / totalShares;
        uint256 maxReward = _sharesAmount * maxAPRs[stakeType] / BASIS_POINTS;
        if (reward > maxReward) {
            reward = maxReward;
        }
        return reward + base;
    }

function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        uint256 accountBalance = _balances[account];
        require(accountBalance >= amount, "ERC20: burn amount exceeds balance");
        unchecked {
            _balances[account] = accountBalance - amount;
            // Overflow not possible: amount <= accountBalance <= totalSupply.
            _totalSupply -= amount;
        }

        emit Transfer(account, address(0), amount);

        _afterTokenTransfer(account, address(0), amount);
    }

function calculateCorrectionFactor(StakeType stakeType) public view returns (uint256) {
        // 计算所有池的总加权质押量
        uint256 totalWeightedShares = 0;
        for (uint256 i = 0; i < 5; i++) {
            StakeType currentType = StakeType(i);
            totalWeightedShares += maxAPRs[currentType] * totalSharesByStakeType[currentType];
        }
        // 避免除以零
        if (totalWeightedShares == 0) {
            return 1;
        }

        // 计算指定池的加权质押量
        uint256 weightedShares = maxAPRs[stakeType] * totalSharesByStakeType[stakeType];

        // 计算占总质押的百分比
        uint256 percentOfTotalShares = totalSharesByStakeType[stakeType] * BASIS_POINTS / totalWeightedShares;

        // 如果百分比为0，避免除以零
        if (percentOfTotalShares == 0) {
            return (weightedShares * BASIS_POINTS) / totalWeightedShares;
        }

        return (weightedShares * BASIS_POINTS) / totalWeightedShares;
    }

function mint() external {
    MintStatus status = mintStatus();
    if (status != MintStatus.Active) {
      revert MintNotActive(status);
    }

    if (hasMinted[msg.sender]) {
      revert AlreadyMinted(msg.sender);
    }

    uint256 tokenId = _nextTokenId;

    if (tokenId > MAX_SUPPLY) {
      revert MaxSupplyReached();
    }

    hasMinted[msg.sender] = true;

    unchecked {
      _nextTokenId = tokenId + 1;
    }

    _safeMint(msg.sender, tokenId);
  }

function mintStatus() public view returns (MintStatus) {
    if (mintClosed) {
      return MintStatus.Closed;
    }
    if (block.timestamp < mintStartTime) {
      return MintStatus.NotStarted;
    }
    if (block.timestamp >= mintEndTime) {
      return MintStatus.Ended;
    }
    return MintStatus.Active;
  }

function _safeMint(address to, uint256 tokenId) internal {
        _safeMint(to, tokenId, "");
    }

function _safeMint(address to, uint256 tokenId, bytes memory data) internal virtual {
        _mint(to, tokenId);
        ERC721Utils.checkOnERC721Received(_msgSender(), address(0), to, tokenId, data);
    }

function _mint(address to, uint256 tokenId) internal {
        if (to == address(0)) {
            revert ERC721InvalidReceiver(address(0));
        }
        address previousOwner = _update(to, tokenId, address(0));
        if (previousOwner != address(0)) {
            revert ERC721InvalidSender(address(0));
        }
    }

function checkOnERC721Received(
        address operator,
        address from,
        address to,
        uint256 tokenId,
        bytes memory data
    ) internal {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(operator, from, tokenId, data) returns (bytes4 retval) {
                if (retval != IERC721Receiver.onERC721Received.selector) {
                    // Token rejected
                    revert IERC721Errors.ERC721InvalidReceiver(to);
                }
            } catch (bytes memory reason) {
                if (reason.length == 0) {
                    // non-IERC721Receiver implementer
                    revert IERC721Errors.ERC721InvalidReceiver(to);
                } else {
                    assembly ("memory-safe") {
                        revert(add(reason, 0x20), mload(reason))
                    }
                }
            }
        }
    }

function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }

function _update(
    address to,
    uint256 tokenId,
    address auth
  ) internal override(ERC721Enumerable) returns (address) {
    return super._update(to, tokenId, auth);
  }

function _update(address to, uint256 tokenId, address auth) internal virtual returns (address) {
        address from = _ownerOf(tokenId);

        // Perform (optional) operator check
        if (auth != address(0)) {
            _checkAuthorized(from, auth, tokenId);
        }

        // Execute the update
        if (from != address(0)) {
            // Clear approval. No need to re-authorize or emit the Approval event
            _approve(address(0), tokenId, address(0), false);

            unchecked {
                _balances[from] -= 1;
            }
        }

        if (to != address(0)) {
            unchecked {
                _balances[to] += 1;
            }
        }

        _owners[tokenId] = to;

        emit Transfer(from, to, tokenId);

        return from;
    }

function _update(address to, uint256 tokenId, address auth) internal virtual override returns (address) {
        address previousOwner = super._update(to, tokenId, auth);

        if (previousOwner == address(0)) {
            _addTokenToAllTokensEnumeration(tokenId);
        } else if (previousOwner != to) {
            _removeTokenFromOwnerEnumeration(previousOwner, tokenId);
        }
        if (to == address(0)) {
            _removeTokenFromAllTokensEnumeration(tokenId);
        } else if (previousOwner != to) {
            _addTokenToOwnerEnumeration(to, tokenId);
        }

        return previousOwner;
    }

function _ownerOf(uint256 tokenId) internal view virtual returns (address) {
        return _owners[tokenId];
    }

function _checkAuthorized(address owner, address spender, uint256 tokenId) internal view virtual {
        if (!_isAuthorized(owner, spender, tokenId)) {
            if (owner == address(0)) {
                revert ERC721NonexistentToken(tokenId);
            } else {
                revert ERC721InsufficientApproval(spender, tokenId);
            }
        }
    }

function createComplianceToken(
        string memory name,
        string memory symbol
    ) external onlyOwner returns (address proxy) {
        // Encode initialization data
        bytes memory initData = abi.encodeWithSelector(
            ComplianceToken.initialize.selector,
            name,
            symbol
        );

        // Deploy proxy contract
        proxy = address(new ERC1967Proxy(implementation, initData));

        // Mark as created token and add to array
        isCreatedToken[proxy] = true;
        createdTokens.push(proxy);

        emit TokenCreated(proxy, name, symbol, address(0));

        return proxy;
    }

function makeOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    )
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        _validateOffer(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        uint256 totalOfferValue = amount * pricePerToken;
        uint256 offerId = _nextOfferId++;
        _handlePayment(
            paymentToken,
            msg.sender,
            address(this),
            totalOfferValue,
            msg.value
        );
        if (paymentToken == address(0)) {
            marketplaceVaultContract.depositOfferFunds{value: totalOfferValue}(
                offerId
            );
        } else {
            IERC20 token = IERC20(paymentToken);
            token.approve(address(marketplaceVaultContract), totalOfferValue);
            marketplaceVaultContract.depositOfferERC20Funds(
                offerId,
                paymentToken,
                totalOfferValue,
                address(this)
            );
        }
        offers[offerId] = AsteroidXMarketplaceStructs.Offer({
            offerId: offerId,
            buyer: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeOffersByToken[tokenId].add(offerId);
        activeOffersByBuyer[msg.sender].add(offerId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.MAKE_OFFER,
            msg.sender,
            address(marketplaceVaultContract),
            amount,
            pricePerToken,
            paymentToken,
            offerId
        );
        emit OfferCreated(
            offerId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        address fundsWallet = IERC1155AsteroidX(address(asteroidXToken))
            .fundsWallet(tokenId);
        if (fundsWallet == address(0)) {
            revert TokenDoesNotExist(tokenId);
        }
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidOfferAmount(amount);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidOfferPrice(pricePerToken);
        if (expirationTime <= block.timestamp)
            revert OfferExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
    }

function _handlePayment(
        address paymentToken,
        address from,
        address to,
        uint256 amount,
        uint256 msgValue
    ) internal {
        if (paymentToken == address(0)) {
            if (msgValue < amount) revert InsufficientETHSent(msgValue, amount);
            if (amount > 0) {
                (bool success, ) = payable(to).call{value: amount}("");
                if (!success) revert EthTransferFailed(to);
            }
            if (msgValue > amount) {
                uint256 excessToRefund = msgValue - amount;
                (bool refundSuccess, ) = payable(from).call{
                    value: excessToRefund
                }("");
                if (!refundSuccess) revert EthRefundFailed(from);
            }
        } else {
            if (!_supportedPaymentTokensSet.contains(paymentToken))
                revert UnsupportedPaymentToken(paymentToken);
            if (msgValue != 0) revert UnexpectedETHPayment();
            IERC20 token = IERC20(paymentToken);
            if (token.allowance(from, address(this)) < amount)
                revert InsufficientAllowance(
                    amount,
                    token.allowance(from, address(this)),
                    paymentToken
                );
            if (token.balanceOf(from) < amount)
                revert InsufficientBalance(
                    amount,
                    token.balanceOf(from),
                    paymentToken
                );
            token.safeTransferFrom(from, to, amount);
        }
    }

