function toInt256(uint256 y) internal pure returns (int256 z) {
        require(y < 2**255);
        z = int256(y);
    }

function toAddress(bytes memory _bytes, uint256 _start) internal pure returns (address) {
        require(_start + 20 >= _start, 'toAddress_overflow');
        require(_bytes.length >= _start + 20, 'toAddress_outOfBounds');
        address tempAddress;

        assembly {
            tempAddress := div(mload(add(add(_bytes, 0x20), _start)), 0x1000000000000000000000000)
        }

        return tempAddress;
    }

function toUint24(bytes memory _bytes, uint256 _start) internal pure returns (uint24) {
        require(_start + 3 >= _start, 'toUint24_overflow');
        require(_bytes.length >= _start + 3, 'toUint24_outOfBounds');
        uint24 tempUint;

        assembly {
            tempUint := mload(add(add(_bytes, 0x3), _start))
        }

        return tempUint;
    }

function computeAddress(address factory, PoolKey memory key) internal pure returns (address pool) {
        require(key.token0 < key.token1);
        pool = address(
            uint256(
                keccak256(
                    abi.encodePacked(
                        hex'ff',
                        factory,
                        keccak256(abi.encode(key.token0, key.token1, key.fee)),
                        POOL_INIT_CODE_HASH
                    )
                )
            )
        );
    }

function getPoolKey(
        address tokenA,
        address tokenB,
        uint24 fee
    ) internal pure returns (PoolKey memory) {
        if (tokenA > tokenB) (tokenA, tokenB) = (tokenB, tokenA);
        return PoolKey({token0: tokenA, token1: tokenB, fee: fee});
    }

function add(uint256 x, uint256 y) internal pure returns (uint256 z) {
        require((z = x + y) >= x);
    }

function add(int256 x, int256 y) internal pure returns (int256 z) {
        require((z = x + y) >= x == (y >= 0));
    }

function acceptOffer(uint256 offerId)
        external
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer == msg.sender) revert CannotAcceptOwnOffer();
        if (block.timestamp >= offer.expirationTime)
            revert OfferExpired(offerId, offer.expirationTime);

        IERC1155AsteroidX token = asteroidXToken;
        if (token.balanceOf(msg.sender, offer.tokenId) < offer.amount)
            revert InsufficientTokenBalance(offer.tokenId, offer.amount);

        uint256 totalOfferValue = offer.amount * offer.pricePerToken;
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalOfferValue,
            offer.paymentToken
        );

        _transferNFT(
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            true
        );
        _handleOfferFundWithdrawal(
            offerId,
            offer.paymentToken,
            msg.sender,
            feeRecipient,
            sellerProceeds,
            platformFee
        );
        _deactivateOffer(offerId);
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER,
            msg.sender,
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferAccepted(
            offerId,
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            totalOfferValue,
            block.timestamp,
            offer.paymentToken
        );
    }

function _calculateFees(uint256 totalAmount, address paymentToken)
        internal
        view
        returns (uint256 platformFee, uint256 sellerProceeds)
    {
        uint256 feeRateToUse = paymentTokenFeeRates[paymentToken];
        platformFee = (feeRateToUse > 0 && totalAmount > 0)
            ? Math.mulDiv(totalAmount, feeRateToUse, 10000)
            : 0;
        sellerProceeds = totalAmount - platformFee;
        return (platformFee, sellerProceeds);
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                address(marketplaceVaultContract),
                tokenId,
                amount,
                ""
            );
            marketplaceVaultContract.transferNFTToBuyer(
                address(asteroidXToken),
                tokenId,
                amount,
                to
            );
        } else {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                to,
                tokenId,
                amount,
                ""
            );
        }
    }

function _handleOfferFundWithdrawal(
        uint256 offerId,
        address paymentToken,
        address seller,
        address feeRecipientAddress,
        uint256 sellerProceeds,
        uint256 platformFee
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.withdrawOfferFundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee
            );
        } else {
            marketplaceVaultContract.withdrawOfferERC20FundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee,
                paymentToken
            );
        }
    }

function _deactivateOffer(uint256 offerId) internal {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) return;
        offer.active = false;
        activeOffersByToken[offer.tokenId].remove(offerId);
        activeOffersByBuyer[offer.buyer].remove(offerId);
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

function mulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 result) {
        unchecked {
            (uint256 high, uint256 low) = mul512(x, y);

            // Handle non-overflow cases, 256 by 256 division.
            if (high == 0) {
                // Solidity will revert if denominator == 0, unlike the div opcode on its own.
                // The surrounding unchecked block does not change this fact.
                // See https://docs.soliditylang.org/en/latest/control-structures.html#checked-or-unchecked-arithmetic.
                return low / denominator;
            }

            // Make sure the result is less than 2²⁵⁶. Also prevents denominator == 0.
            if (denominator <= high) {
                Panic.panic(ternary(denominator == 0, Panic.DIVISION_BY_ZERO, Panic.UNDER_OVERFLOW));
            }

            ///////////////////////////////////////////////
            // 512 by 256 division.
            ///////////////////////////////////////////////

            // Make division exact by subtracting the remainder from [high low].
            uint256 remainder;
            assembly ("memory-safe") {
                // Compute remainder using mulmod.
                remainder := mulmod(x, y, denominator)

                // Subtract 256 bit number from 512 bit number.
                high := sub(high, gt(remainder, low))
                low := sub(low, remainder)
            }

            // Factor powers of two out of denominator and compute largest power of two divisor of denominator.
            // Always >= 1. See https://cs.stackexchange.com/q/138556/92363.

            uint256 twos = denominator & (0 - denominator);
            assembly ("memory-safe") {
                // Divide denominator by twos.
                denominator := div(denominator, twos)

                // Divide [high low] by twos.
                low := div(low, twos)

                // Flip twos such that it is 2²⁵⁶ / twos. If twos is zero, then it becomes one.
                twos := add(div(sub(0, twos), twos), 1)
            }

            // Shift in bits from high into low.
            low |= high * twos;

            // Invert denominator mod 2²⁵⁶. Now that denominator is an odd number, it has an inverse modulo 2²⁵⁶ such
            // that denominator * inv ≡ 1 mod 2²⁵⁶. Compute the inverse by starting with a seed that is correct for
            // four bits. That is, denominator * inv ≡ 1 mod 2⁴.
            uint256 inverse = (3 * denominator) ^ 2;

            // Use the Newton-Raphson iteration to improve the precision. Thanks to Hensel's lifting lemma, this also
            // works in modular arithmetic, doubling the correct bits in each step.
            inverse *= 2 - denominator * inverse; // inverse mod 2⁸
            inverse *= 2 - denominator * inverse; // inverse mod 2¹⁶
            inverse *= 2 - denominator * inverse; // inverse mod 2³²
            inverse *= 2 - denominator * inverse; // inverse mod 2⁶⁴
            inverse *= 2 - denominator * inverse; // inverse mod 2¹²⁸
            inverse *= 2 - denominator * inverse; // inverse mod 2²⁵⁶

            // Because the division is now exact we can divide by multiplying with the modular inverse of denominator.
            // This will give us the correct result modulo 2²⁵⁶. Since the preconditions guarantee that the outcome is
            // less than 2²⁵⁶, this is the final result. We don't need to compute the high bits of the result and high
            // is no longer required.
            result = low * inverse;
            return result;
        }
    }

function mulDiv(uint256 x, uint256 y, uint256 denominator, Rounding rounding) internal pure returns (uint256) {
        return mulDiv(x, y, denominator) + SafeCast.toUint(unsignedRoundsUp(rounding) && mulmod(x, y, denominator) > 0);
    }

function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

function transferNFTToBuyer(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (buyer == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            buyer,
            tokenId,
            amount,
            ""
        );
        emit NFTTransferredToBuyer(tokenContract, tokenId, amount, buyer);
    }

function withdrawOfferFundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        uint256 totalAmount = sellerProceeds + platformFee;
        if (totalAmount > address(this).balance) revert InsufficientBalance();

        // First transfer to seller
        payable(seller).sendValue(sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            payable(platformFeeRecipient).sendValue(platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function withdrawOfferERC20FundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        // Get the ERC20 token contract
        IERC20 erc20Token = IERC20(token);

        // First transfer to seller
        erc20Token.safeTransfer(seller, sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            erc20Token.safeTransfer(platformFeeRecipient, platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function removeLiquidityETH(
        address token,
        uint liquidity,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) public virtual override ensure(deadline) returns (uint amountToken, uint amountETH) {
        (amountToken, amountETH) = removeLiquidity(
            token,
            WETH,
            liquidity,
            amountTokenMin,
            amountETHMin,
            address(this),
            deadline
        );
        TransferHelper.safeTransfer(token, to, amountToken);
        IWETH(WETH).withdraw(amountETH);
        TransferHelper.safeTransferETH(to, amountETH);
    }

function removeLiquidity(
        address tokenA,
        address tokenB,
        uint liquidity,
        uint amountAMin,
        uint amountBMin,
        address to,
        uint deadline
    ) public virtual override ensure(deadline) returns (uint amountA, uint amountB) {
        address pair = HyperindexV2Library.pairFor(factory, tokenA, tokenB);
        IHyperindexV2Pair(pair).transferFrom(msg.sender, pair, liquidity); // send liquidity to pair
        (uint amount0, uint amount1) = IHyperindexV2Pair(pair).burn(to);
        (address token0,) = HyperindexV2Library.sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        require(amountA >= amountAMin, 'HyperindexV2Router: INSUFFICIENT_A_AMOUNT');
        require(amountB >= amountBMin, 'HyperindexV2Router: INSUFFICIENT_B_AMOUNT');
    }

function safeTransfer(address token, address to, uint value) internal {
        // bytes4(keccak256(bytes('transfer(address,uint256)')));
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), 'TransferHelper: TRANSFER_FAILED');
    }

function safeTransferETH(address to, uint value) internal {
        (bool success,) = to.call{value:value}(new bytes(0));
        require(success, 'TransferHelper: ETH_TRANSFER_FAILED');
    }

function pairFor(address tokenA, address tokenB) public view returns (address pair) {
        pair = HyperindexV2Library.pairFor(factory, tokenA, tokenB);
    }

function pairFor(address factory, address tokenA, address tokenB) internal pure returns (address pair) {
        (address token0, address token1) = sortTokens(tokenA, tokenB);
        pair = address(uint160(uint(keccak256(abi.encodePacked(
                hex'ff',
                factory,
                keccak256(abi.encodePacked(token0, token1)),
                hex'b4d4d093a282c5a30c7e0d37bec53ad1405404abac87cc046ceb2740307290e4' // init code hash
            )))));
    }

function sortTokens(address tokenA, address tokenB) internal pure returns (address token0, address token1) {
        require(tokenA != tokenB, 'HyperindexV2Library: IDENTICAL_ADDRESSES');
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), 'HyperindexV2Library: ZERO_ADDRESS');
    }

function swapExactETHForTokens(uint amountOutMin, address[] calldata path, address to, uint deadline)
        external
        virtual
        override
        payable
        ensure(deadline)
        returns (uint[] memory amounts)
    {
        require(path[0] == WETH, 'HyperindexV2Router: INVALID_PATH');
        amounts = HyperindexV2Library.getAmountsOut(factory, msg.value, path);
        require(amounts[amounts.length - 1] >= amountOutMin, 'HyperindexV2Router: INSUFFICIENT_OUTPUT_AMOUNT');
        IWETH(WETH).deposit{value: amounts[0]}();
        assert(IWETH(WETH).transfer(HyperindexV2Library.pairFor(factory, path[0], path[1]), amounts[0]));
        _swap(amounts, path, to);
    }

function getAmountsOut(uint amountIn, address[] memory path)
        public
        view
        virtual
        override
        returns (uint[] memory amounts)
    {
        return HyperindexV2Library.getAmountsOut(factory, amountIn, path);
    }

function getAmountsOut(address factory, uint amountIn, address[] memory path) internal view returns (uint[] memory amounts) {
        require(path.length >= 2, 'HyperindexV2Library: INVALID_PATH');
        amounts = new uint[](path.length);
        amounts[0] = amountIn;
        for (uint i; i < path.length - 1; i++) {
            (uint reserveIn, uint reserveOut) = getReserves(factory, path[i], path[i + 1]);
            amounts[i + 1] = getAmountOut(amounts[i], reserveIn, reserveOut);
        }
    }

function pairFor(address tokenA, address tokenB) public view returns (address pair) {
        pair = HyperindexV2Library.pairFor(factory, tokenA, tokenB);
    }

function pairFor(address factory, address tokenA, address tokenB) internal pure returns (address pair) {
        (address token0, address token1) = sortTokens(tokenA, tokenB);
        pair = address(uint160(uint(keccak256(abi.encodePacked(
                hex'ff',
                factory,
                keccak256(abi.encodePacked(token0, token1)),
                hex'b4d4d093a282c5a30c7e0d37bec53ad1405404abac87cc046ceb2740307290e4' // init code hash
            )))));
    }

function _swap(uint[] memory amounts, address[] memory path, address _to) internal virtual {
        for (uint i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0,) = HyperindexV2Library.sortTokens(input, output);
            uint amountOut = amounts[i + 1];
            (uint amount0Out, uint amount1Out) = input == token0 ? (uint(0), amountOut) : (amountOut, uint(0));
            address to = i < path.length - 2 ? HyperindexV2Library.pairFor(factory, output, path[i + 2]) : _to;
            IHyperindexV2Pair(HyperindexV2Library.pairFor(factory, input, output)).swap(
                amount0Out, amount1Out, to, new bytes(0)
            );
        }
    }

function getReserves(address factory, address tokenA, address tokenB) internal view returns (uint reserveA, uint reserveB) {
        (address token0,) = sortTokens(tokenA, tokenB);
        (uint reserve0, uint reserve1,) = IHyperindexV2Pair(pairFor(factory, tokenA, tokenB)).getReserves();
        (reserveA, reserveB) = tokenA == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
    }

function getAmountOut(uint amountIn, uint reserveIn, uint reserveOut)
        public
        pure
        virtual
        override
        returns (uint amountOut)
    {
        return HyperindexV2Library.getAmountOut(amountIn, reserveIn, reserveOut);
    }

function getAmountOut(uint amountIn, uint reserveIn, uint reserveOut) internal pure returns (uint amountOut) {
        require(amountIn > 0, 'HyperindexV2Library: INSUFFICIENT_INPUT_AMOUNT');
        require(reserveIn > 0 && reserveOut > 0, 'HyperindexV2Library: INSUFFICIENT_LIQUIDITY');
        uint amountInWithFee = amountIn.mul(997);
        uint numerator = amountInWithFee.mul(reserveOut);
        uint denominator = reserveIn.mul(1000).add(amountInWithFee);
        amountOut = numerator / denominator;
    }

function sortTokens(address tokenA, address tokenB) internal pure returns (address token0, address token1) {
        require(tokenA != tokenB, 'HyperindexV2Library: IDENTICAL_ADDRESSES');
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), 'HyperindexV2Library: ZERO_ADDRESS');
    }

function mul(uint x, uint y) internal pure returns (uint z) {
        require(y == 0 || (z = x * y) / y == x, 'ds-math-mul-overflow');
    }

function add(uint x, uint y) internal pure returns (uint z) {
        require((z = x + y) >= x, 'ds-math-add-overflow');
    }

