function transferNFTToBuyer(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (buyer == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            buyer,
            tokenId,
            amount,
            ""
        );
        emit NFTTransferredToBuyer(tokenContract, tokenId, amount, buyer);
    }

function withdrawOfferFundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        uint256 totalAmount = sellerProceeds + platformFee;
        if (totalAmount > address(this).balance) revert InsufficientBalance();

        // First transfer to seller
        payable(seller).sendValue(sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            payable(platformFeeRecipient).sendValue(platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function withdrawOfferERC20FundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        // Get the ERC20 token contract
        IERC20 erc20Token = IERC20(token);

        // First transfer to seller
        erc20Token.safeTransfer(seller, sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            erc20Token.safeTransfer(platformFeeRecipient, platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function makeOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    )
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        _validateOffer(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        uint256 totalOfferValue = amount * pricePerToken;
        uint256 offerId = _nextOfferId++;
        _handlePayment(
            paymentToken,
            msg.sender,
            address(this),
            totalOfferValue,
            msg.value
        );
        if (paymentToken == address(0)) {
            marketplaceVaultContract.depositOfferFunds{value: totalOfferValue}(
                offerId
            );
        } else {
            IERC20 token = IERC20(paymentToken);
            token.approve(address(marketplaceVaultContract), totalOfferValue);
            marketplaceVaultContract.depositOfferERC20Funds(
                offerId,
                paymentToken,
                totalOfferValue,
                address(this)
            );
        }
        offers[offerId] = AsteroidXMarketplaceStructs.Offer({
            offerId: offerId,
            buyer: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeOffersByToken[tokenId].add(offerId);
        activeOffersByBuyer[msg.sender].add(offerId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.MAKE_OFFER,
            msg.sender,
            address(marketplaceVaultContract),
            amount,
            pricePerToken,
            paymentToken,
            offerId
        );
        emit OfferCreated(
            offerId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        address fundsWallet = IERC1155AsteroidX(address(asteroidXToken))
            .fundsWallet(tokenId);
        if (fundsWallet == address(0)) {
            revert TokenDoesNotExist(tokenId);
        }
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidOfferAmount(amount);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidOfferPrice(pricePerToken);
        if (expirationTime <= block.timestamp)
            revert OfferExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
    }

function _handlePayment(
        address paymentToken,
        address from,
        address to,
        uint256 amount,
        uint256 msgValue
    ) internal {
        if (paymentToken == address(0)) {
            if (msgValue < amount) revert InsufficientETHSent(msgValue, amount);
            if (amount > 0) {
                (bool success, ) = payable(to).call{value: amount}("");
                if (!success) revert EthTransferFailed(to);
            }
            if (msgValue > amount) {
                uint256 excessToRefund = msgValue - amount;
                (bool refundSuccess, ) = payable(from).call{
                    value: excessToRefund
                }("");
                if (!refundSuccess) revert EthRefundFailed(from);
            }
        } else {
            if (!_supportedPaymentTokensSet.contains(paymentToken))
                revert UnsupportedPaymentToken(paymentToken);
            if (msgValue != 0) revert UnexpectedETHPayment();
            IERC20 token = IERC20(paymentToken);
            if (token.allowance(from, address(this)) < amount)
                revert InsufficientAllowance(
                    amount,
                    token.allowance(from, address(this)),
                    paymentToken
                );
            if (token.balanceOf(from) < amount)
                revert InsufficientBalance(
                    amount,
                    token.balanceOf(from),
                    paymentToken
                );
            token.safeTransferFrom(from, to, amount);
        }
    }

function depositOfferERC20Funds(
        uint256 offerId,
        address token,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (token == address(0)) revert InvalidTokenContract();
        if (amount == 0) revert InvalidAmount();

        // Transfer ERC20 tokens from buyer to this contract
        IERC20(token).safeTransferFrom(buyer, address(this), amount);

        emit OfferFundsDeposited(offerId, amount);
    }

