    }

function swapExactETHForTokens(uint amountOutMin, route[] calldata routes, address to, uint deadline)
    external
    payable
    ensure(deadline)
    returns (uint[] memory amounts)
    {
        require(routes[0].from == address(weth), 'Router: INVALID_PATH');
        amounts = getAmountsOut(msg.value, routes);
        require(amounts[amounts.length - 1] >= amountOutMin, 'Router: INSUFFICIENT_OUTPUT_AMOUNT');
        weth.deposit{value: amounts[0]}();
        assert(weth.transfer(pairFor(routes[0].from, routes[0].to, routes[0].stable), amounts[0]));
        _swap(amounts, routes, to);
    }

function getAmountsOut(uint amountIn, route[] memory routes) public view returns (uint[] memory amounts) {
        require(routes.length >= 1, 'Router: INVALID_PATH');
        amounts = new uint[](routes.length+1);
        amounts[0] = amountIn;
        for (uint i = 0; i < routes.length; i++) {
            address pair = pairFor(routes[i].from, routes[i].to, routes[i].stable);
            if (IPairFactory(factory).isPair(pair)) {
                amounts[i+1] = IPair(pair).getAmountOut(amounts[i], routes[i].from);
            }
        }
    }

function pairFor(address tokenA, address tokenB, bool stable) public view returns (address pair) {
//        (address token0, address token1) = sortTokens(tokenA, tokenB);
//        pair = address(uint160(uint256(keccak256(abi.encodePacked(
//            hex'ff',
//            factory,
//            keccak256(abi.encodePacked(token0, token1, stable)),
//            pairCodeHash // init code hash
//        )))));
        pair = IPairFactory(factory).getPair(tokenA, tokenB, stable);
    }

function _swap(uint[] memory amounts, route[] memory routes, address _to) internal virtual {
        for (uint i = 0; i < routes.length; i++) {
            (address token0,) = sortTokens(routes[i].from, routes[i].to);
            uint amountOut = amounts[i + 1];
            (uint amount0Out, uint amount1Out) = routes[i].from == token0 ? (uint(0), amountOut) : (amountOut, uint(0));
            address to = i < routes.length - 1 ? pairFor(routes[i+1].from, routes[i+1].to, routes[i+1].stable) : _to;
            IPair(pairFor(routes[i].from, routes[i].to, routes[i].stable)).swap(
                amount0Out, amount1Out, to, new bytes(0)
            );
        }
    }

function isPair(address pair) external view returns (bool) {
        return IPairFactory(factory).isPair(pair);
    }

function getAmountOut(uint amountIn, address tokenIn, address tokenOut) external view returns (uint amount, bool stable) {
        address pair = pairFor(tokenIn, tokenOut, true);
        uint amountStable;
        uint amountVolatile;
        if (IPairFactory(factory).isPair(pair)) {
            amountStable = IPair(pair).getAmountOut(amountIn, tokenIn);
        }
        pair = pairFor(tokenIn, tokenOut, false);
        if (IPairFactory(factory).isPair(pair)) {
            amountVolatile = IPair(pair).getAmountOut(amountIn, tokenIn);
        }
        return amountStable > amountVolatile ? (amountStable, true) : (amountVolatile, false);
    }

function sortTokens(address tokenA, address tokenB) public pure returns (address token0, address token1) {
        require(tokenA != tokenB, 'Router: IDENTICAL_ADDRESSES');
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), 'Router: ZERO_ADDRESS');
    }

function makeOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    )
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        _validateOffer(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        uint256 totalOfferValue = amount * pricePerToken;
        uint256 offerId = _nextOfferId++;
        _handlePayment(
            paymentToken,
            msg.sender,
            address(this),
            totalOfferValue,
            msg.value
        );
        if (paymentToken == address(0)) {
            marketplaceVaultContract.depositOfferFunds{value: totalOfferValue}(
                offerId
            );
        } else {
            IERC20 token = IERC20(paymentToken);
            token.approve(address(marketplaceVaultContract), totalOfferValue);
            marketplaceVaultContract.depositOfferERC20Funds(
                offerId,
                paymentToken,
                totalOfferValue,
                address(this)
            );
        }
        offers[offerId] = AsteroidXMarketplaceStructs.Offer({
            offerId: offerId,
            buyer: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeOffersByToken[tokenId].add(offerId);
        activeOffersByBuyer[msg.sender].add(offerId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.MAKE_OFFER,
            msg.sender,
            address(marketplaceVaultContract),
            amount,
            pricePerToken,
            paymentToken,
            offerId
        );
        emit OfferCreated(
            offerId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        address fundsWallet = IERC1155AsteroidX(address(asteroidXToken))
            .fundsWallet(tokenId);
        if (fundsWallet == address(0)) {
            revert TokenDoesNotExist(tokenId);
        }
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidOfferAmount(amount);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidOfferPrice(pricePerToken);
        if (expirationTime <= block.timestamp)
            revert OfferExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
    }

function _handlePayment(
        address paymentToken,
        address from,
        address to,
        uint256 amount,
        uint256 msgValue
    ) internal {
        if (paymentToken == address(0)) {
            if (msgValue < amount) revert InsufficientETHSent(msgValue, amount);
            if (amount > 0) {
                (bool success, ) = payable(to).call{value: amount}("");
                if (!success) revert EthTransferFailed(to);
            }
            if (msgValue > amount) {
                uint256 excessToRefund = msgValue - amount;
                (bool refundSuccess, ) = payable(from).call{
                    value: excessToRefund
                }("");
                if (!refundSuccess) revert EthRefundFailed(from);
            }
        } else {
            if (!_supportedPaymentTokensSet.contains(paymentToken))
                revert UnsupportedPaymentToken(paymentToken);
            if (msgValue != 0) revert UnexpectedETHPayment();
            IERC20 token = IERC20(paymentToken);
            if (token.allowance(from, address(this)) < amount)
                revert InsufficientAllowance(
                    amount,
                    token.allowance(from, address(this)),
                    paymentToken
                );
            if (token.balanceOf(from) < amount)
                revert InsufficientBalance(
                    amount,
                    token.balanceOf(from),
                    paymentToken
                );
            token.safeTransferFrom(from, to, amount);
        }
    }

function depositOfferERC20Funds(
        uint256 offerId,
        address token,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (token == address(0)) revert InvalidTokenContract();
        if (amount == 0) revert InvalidAmount();

        // Transfer ERC20 tokens from buyer to this contract
        IERC20(token).safeTransferFrom(buyer, address(this), amount);

        emit OfferFundsDeposited(offerId, amount);
    }

