function lock(uint256 ruleId) public nonReentrant {
        require(!isPausingForOperation, "Contract is pausing for operation.");
        LockRule memory ruleInfo = lockRules[ruleId];
        require(ruleInfo.isValid, "Staking is invalid.");
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "No more supply.");

        uint256 LOCK_AMOUNT = ruleInfo.lockAmount;
        uint256 fee = LOCK_AMOUNT * FEE_RATE / 10000;
        uint256 lockAmount = LOCK_AMOUNT - fee;
        bool feeSuccess = tokenATT.transferFrom(msg.sender, FEE_HOLDER, fee);
        require(feeSuccess, "Token transfer failed");
        bool lockSuccess = tokenATT.transferFrom(msg.sender, address(this), lockAmount);
        require(lockSuccess, "Token transfer failed");

        // Save user info
        userCurrentLockedId[msg.sender] += 1;
        userLockInfo[msg.sender][userCurrentLockedId[msg.sender]] = LockInfo(
            ruleId, msg.sender, userCurrentLockedId[msg.sender],
            lockAmount, block.timestamp, UNLOCK_DURATION,
            block.timestamp + UNLOCK_DURATION, ruleInfo.rewardsAmount, false
        );

        // Send rewards
        SUPPLY_LIMIT -= ruleInfo.rewardsAmount;
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "Insufficient supply limit.");
        (bool rewardSuccess, ) = payable(msg.sender).call{value: ruleInfo.rewardsAmount}("");
        require(rewardSuccess, "Rewards failed");


        emit Lock(msg.sender, ruleId, lockAmount, block.timestamp);
    }

function cancelOffer(uint256 offerId)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer != msg.sender) revert NotBuyer(offerId, msg.sender);
        _deactivateOffer(offerId);
        uint256 refundAmount = offer.amount * offer.pricePerToken;
        _handleOfferFundRefund(
            offerId,
            offer.paymentToken,
            msg.sender,
            refundAmount
        );
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.CANCEL_OFFER,
            address(marketplaceVaultContract),
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferCancelled(offerId);
    }

function _deactivateOffer(uint256 offerId) internal {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) return;
        offer.active = false;
        activeOffersByToken[offer.tokenId].remove(offerId);
        activeOffersByBuyer[offer.buyer].remove(offerId);
    }

function _handleOfferFundRefund(
        uint256 offerId,
        address paymentToken,
        address buyer,
        uint256 refundAmount
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.refundOfferFundsToBuyer(
                offerId,
                buyer,
                refundAmount
            );
        } else {
            marketplaceVaultContract.refundOfferERC20FundsToBuyer(
                offerId,
                buyer,
                refundAmount,
                paymentToken
            );
        }
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

