function mint() external {
    MintStatus status = mintStatus();
    if (status != MintStatus.Active) {
      revert MintNotActive(status);
    }

    if (hasMinted[msg.sender]) {
      revert AlreadyMinted(msg.sender);
    }

    uint256 tokenId = _nextTokenId;

    if (tokenId > MAX_SUPPLY) {
      revert MaxSupplyReached();
    }

    hasMinted[msg.sender] = true;

    unchecked {
      _nextTokenId = tokenId + 1;
    }

    _safeMint(msg.sender, tokenId);
  }

function mintStatus() public view returns (MintStatus) {
    if (mintClosed) {
      return MintStatus.Closed;
    }
    if (block.timestamp < mintStartTime) {
      return MintStatus.NotStarted;
    }
    if (block.timestamp >= mintEndTime) {
      return MintStatus.Ended;
    }
    return MintStatus.Active;
  }

