function lock(uint256 ruleId) public nonReentrant {
        require(!isPausingForOperation, "Contract is pausing for operation.");
        LockRule memory ruleInfo = lockRules[ruleId];
        require(ruleInfo.isValid, "Staking is invalid.");
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "No more supply.");

        uint256 LOCK_AMOUNT = ruleInfo.lockAmount;
        uint256 fee = LOCK_AMOUNT * FEE_RATE / 10000;
        uint256 lockAmount = LOCK_AMOUNT - fee;
        bool feeSuccess = tokenATT.transferFrom(msg.sender, FEE_HOLDER, fee);
        require(feeSuccess, "Token transfer failed");
        bool lockSuccess = tokenATT.transferFrom(msg.sender, address(this), lockAmount);
        require(lockSuccess, "Token transfer failed");

        // Save user info
        userCurrentLockedId[msg.sender] += 1;
        userLockInfo[msg.sender][userCurrentLockedId[msg.sender]] = LockInfo(
            ruleId, msg.sender, userCurrentLockedId[msg.sender],
            lockAmount, block.timestamp, UNLOCK_DURATION,
            block.timestamp + UNLOCK_DURATION, ruleInfo.rewardsAmount, false
        );

        // Send rewards
        SUPPLY_LIMIT -= ruleInfo.rewardsAmount;
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "Insufficient supply limit.");
        (bool rewardSuccess, ) = payable(msg.sender).call{value: ruleInfo.rewardsAmount}("");
        require(rewardSuccess, "Rewards failed");


        emit Lock(msg.sender, ruleId, lockAmount, block.timestamp);
    }

function addLiquidityETH(
    address token,
    uint256 amountTokenDesired,
    uint256 amountTokenMin,
    uint256 amountETHMin,
    address to,
    uint256 deadline
  )
    external
    payable
    virtual
    override
    ensure(deadline)
    returns (uint256 amountToken, uint256 amountETH, uint256 liquidity)
  {
    (amountToken, amountETH) = _addLiquidity(
      token,
      WETH,
      amountTokenDesired,
      msg.value,
      amountTokenMin,
      amountETHMin
    );
    address pair = HuskeyLibrary.pairFor(factory, token, WETH);
    TransferHelper.safeTransferFrom(token, msg.sender, pair, amountToken);
    IWETH(WETH).deposit{ value: amountETH }();
    assert(IWETH(WETH).transfer(pair, amountETH));
    liquidity = IHuskeyPair(pair).mint(to);
    // refund dust eth, if any
    if (msg.value > amountETH)
      TransferHelper.safeTransferETH(msg.sender, msg.value - amountETH);
  }

function _addLiquidity(
    address tokenA,
    address tokenB,
    uint256 amountADesired,
    uint256 amountBDesired,
    uint256 amountAMin,
    uint256 amountBMin
  ) internal virtual returns (uint256 amountA, uint256 amountB) {
    // create the pair if it doesn't exist yet
    if (IHuskeyFactory(factory).getPair(tokenA, tokenB) == address(0)) {
      IHuskeyFactory(factory).createPair(tokenA, tokenB);
    }
    (uint256 reserveA, uint256 reserveB) = HuskeyLibrary.getReserves(
      factory,
      tokenA,
      tokenB
    );
    if (reserveA == 0 && reserveB == 0) {
      (amountA, amountB) = (amountADesired, amountBDesired);
    } else {
      uint256 amountBOptimal = HuskeyLibrary.quote(amountADesired, reserveA, reserveB);
      if (amountBOptimal <= amountBDesired) {
        require(amountBOptimal >= amountBMin, 'HuskeyRouter: INSUFFICIENT_B_AMOUNT');
        (amountA, amountB) = (amountADesired, amountBOptimal);
      } else {
        uint256 amountAOptimal = HuskeyLibrary.quote(amountBDesired, reserveB, reserveA);
        assert(amountAOptimal <= amountADesired);
        require(amountAOptimal >= amountAMin, 'HuskeyRouter: INSUFFICIENT_A_AMOUNT');
        (amountA, amountB) = (amountAOptimal, amountBDesired);
      }
    }
  }

function pairFor(
