function stake(
        uint256 lockPeriod
    ) external 
        payable 
        nonReentrant 
        whenNotPaused 
        notBlacklisted 
        whitelistCheck
        whenNotEmergency  // Add emergency mode check
        returns (uint256) 
    {
        require(block.timestamp < stakeEndTime, "Staking period has ended");

        // Add validation for lockPeriod
        StakingLib.validateAndGetRate(
            lockPeriod, 
            lockOptions,
            historicalRates
        );

        uint256 amount = msg.value;
        amount = StakingLib.validateAndFormatAmount(amount, minStakeAmount);

        if (totalStaked + amount > maxTotalStake) revert MaxTotalStakeExceeded();

        // Calculate potential reward for this new stake
        uint256 rewardRate = StakingLib.validateAndGetRate(
            lockPeriod, 
            lockOptions,
            historicalRates
        );
        uint256 potentialReward = StakingLib.calculateReward(
            amount,
            lockPeriod,  // timeElapsed
            rewardRate,
            lockPeriod    // 移除 block.timestamp
        );

        // Check if reward pool can cover this new stake
        // require(
        //     rewardPoolBalance >= totalPendingRewards + potentialReward,
        //     "Insufficient reward pool"
        // );

        // Update total pending rewards
        totalPendingRewards += potentialReward;

        uint256 positionId = nextPositionId++;
        Position memory newPosition = Position({
            positionId: positionId,
            amount: amount,
            lockPeriod: lockPeriod,
            stakedAt: block.timestamp,
            lastRewardAt: block.timestamp,
            rewardRate: rewardRate,
            isUnstaked: false
        });

        userPositions[msg.sender].push(newPosition);
        userPositionCount[msg.sender]++;
        positionOwner[positionId] = msg.sender;
        userTotalStaked[msg.sender] += amount;
        totalStaked += amount;

        historicalTotalStaked += amount;

        emit PositionCreated(
            msg.sender,
            positionId,
            amount,
            lockPeriod,
            block.timestamp
        );

        return positionId;
    }

function validateAndGetRate(
        uint256 lockPeriod,
        IStaking.LockOption[] memory options,
        mapping(uint256 => uint256) storage historicalRates
    ) public view returns (uint256 rate) {
        // First check current options
        for (uint256 i = 0; i < options.length; i++) {
            if (options[i].period == lockPeriod) {
                return options[i].rewardRate;
            }
        }

        // If not found in current options, check historical rates
        rate = historicalRates[lockPeriod];
        if (rate > 0) {
            return rate;
        }

        revert InvalidPeriod();
    }

function validateAndFormatAmount(
        uint256 amount,
        uint256 minAmount
    ) public pure returns (uint256) {
        if (amount < minAmount) {
            revert InvalidAmount();
        }
        return amount;
    }

function calculateReward(
        uint256 amount,
        uint256 timeElapsed,
        uint256 rewardRate,
        uint256 lockPeriod
    ) public pure returns (uint256 reward) {
        // Early return for zero values
        if (amount == 0 || timeElapsed == 0 || rewardRate == 0) {
            return 0;
        }

        // If current time is beyond lock period, only calculate rewards up to lock end
        if (timeElapsed > lockPeriod) {
            timeElapsed = lockPeriod;
        }

        // High precision calculations using 18 decimals
        uint256 PRECISION = 1e18;

        // Input validation to prevent overflow
        require(amount <= type(uint256).max / PRECISION, "Amount too large");
        require(rewardRate <= BASIS_POINTS, "Rate too large");

        // Calculate annual rate with high precision
        uint256 annualRate = (rewardRate * PRECISION) / BASIS_POINTS;
        require(annualRate <= type(uint256).max / PRECISION, "Annual rate overflow");

        // Calculate complete years and remaining time
        uint256 completeYears = timeElapsed / SECONDS_PER_YEAR;
        uint256 remainingTime = timeElapsed % SECONDS_PER_YEAR;

        // Calculate rewards for complete years
        uint256 totalReward = calculateYearlyReward(amount, annualRate, PRECISION) * completeYears;

        // Calculate rewards for remaining time
        if (remainingTime > 0) {
            totalReward += calculateRemainingTimeReward(
                amount,
                annualRate,
                remainingTime,
                PRECISION
            );
        }

        // Validation check
        require(totalReward <= amount * rewardRate * (timeElapsed / SECONDS_PER_YEAR + 1) / BASIS_POINTS, 
            "Reward overflow");

        return totalReward;
    }

function calculateYearlyReward(
        uint256 amount,
        uint256 annualRate,
        uint256 PRECISION
    ) private pure returns (uint256) {
        return (amount * annualRate) / PRECISION;
    }

function calculateRemainingTimeReward(
        uint256 amount,
        uint256 annualRate,
        uint256 remainingTime,
        uint256 PRECISION
    ) private pure returns (uint256) {
        uint256 timeRatio = (remainingTime * PRECISION) / SECONDS_PER_YEAR;
        return (amount * annualRate * timeRatio) / (PRECISION * PRECISION);
    }

