function depositWithPermit(
        bytes32 orderRef,
        address buyer,
        address seller,
        uint256 amount,
        uint64 deliveryDeadline,
        uint256 authDeadline,
        bytes calldata authSig,
        uint256 permitDeadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant {
        Deal storage deal = _deals[orderRef];
        if (deal.state != State.None) revert InvalidState(deal.state);
        if (amount == 0 || amount > type(uint96).max) revert InvalidAmount();
        if (buyer == address(0) || seller == address(0) || seller == buyer) revert InvalidAddress();
        if (deliveryDeadline <= block.timestamp) revert DeliveryDeadlinePassed();
        if (block.timestamp > authDeadline) revert SignatureExpired();

        _verifyDepositAuthorization(orderRef, buyer, seller, amount, deliveryDeadline, authDeadline, authSig);

        deal.buyer = buyer;
        deal.amount = uint96(amount);
        deal.seller = seller;
        deal.deliveryDeadline = deliveryDeadline;
        deal.state = State.Funded;

        emit Deposited(orderRef, buyer, seller, amount, deliveryDeadline);

        try IERC20Permit(token).permit(buyer, address(this), amount, permitDeadline, v, r, s) {} catch {}
        IERC20(token).safeTransferFrom(buyer, address(this), amount);
    }

function _verifyDepositAuthorization(
        bytes32 orderRef,
        address buyer,
        address seller,
        uint256 amount,
        uint64 deliveryDeadline,
        uint256 authDeadline,
        bytes calldata authSig
    ) private view {
        bytes32 structHash = keccak256(
            abi.encode(DEPOSIT_AUTHORIZATION_TYPEHASH, orderRef, seller, amount, deliveryDeadline, authDeadline)
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        if (!SignatureChecker.isValidSignatureNow(buyer, digest, authSig)) revert InvalidSignature();
    }

function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

function _hashTypedDataV4(bytes32 structHash) internal view virtual returns (bytes32) {
        return MessageHashUtils.toTypedDataHash(_domainSeparatorV4(), structHash);
    }

function isValidSignatureNow(address signer, bytes32 hash, bytes memory signature) internal view returns (bool) {
        if (signer.code.length == 0) {
            (address recovered, ECDSA.RecoverError err, ) = ECDSA.tryRecover(hash, signature);
            return err == ECDSA.RecoverError.NoError && recovered == signer;
        } else {
            return isValidERC1271SignatureNow(signer, hash, signature);
        }
    }

function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

function toTypedDataHash(bytes32 domainSeparator, bytes32 structHash) internal pure returns (bytes32 digest) {
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, hex"19_01")
            mstore(add(ptr, 0x02), domainSeparator)
            mstore(add(ptr, 0x22), structHash)
            digest := keccak256(ptr, 0x42)
        }
    }

function _domainSeparatorV4() internal view returns (bytes32) {
        if (address(this) == _cachedThis && block.chainid == _cachedChainId) {
            return _cachedDomainSeparator;
        } else {
            return _buildDomainSeparator();
        }
    }

function tryRecover(
        bytes32 hash,
        bytes memory signature
    ) internal pure returns (address recovered, RecoverError err, bytes32 errArg) {
        if (signature.length == 65) {
            bytes32 r;
            bytes32 s;
            uint8 v;
            // ecrecover takes the signature parameters, and the only way to get them
            // currently is to use assembly.
            assembly ("memory-safe") {
                r := mload(add(signature, 0x20))
                s := mload(add(signature, 0x40))
                v := byte(0, mload(add(signature, 0x60)))
            }
            return tryRecover(hash, v, r, s);
        } else {
            return (address(0), RecoverError.InvalidSignatureLength, bytes32(signature.length));
        }
    }

function tryRecover(
        bytes32 hash,
        bytes32 r,
        bytes32 vs
    ) internal pure returns (address recovered, RecoverError err, bytes32 errArg) {
        unchecked {
            bytes32 s = vs & bytes32(0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff);
            // We do not check for an overflow here since the shift operation results in 0 or 1.
            uint8 v = uint8((uint256(vs) >> 255) + 27);
            return tryRecover(hash, v, r, s);
        }
    }

function tryRecover(
        bytes32 hash,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) internal pure returns (address recovered, RecoverError err, bytes32 errArg) {
        // EIP-2 still allows signature malleability for ecrecover(). Remove this possibility and make the signature
        // unique. Appendix F in the Ethereum Yellow paper (https://ethereum.github.io/yellowpaper/paper.pdf), defines
        // the valid range for s in (301): 0 < s < secp256k1n ÷ 2 + 1, and for v in (302): v ∈ {27, 28}. Most
        // signatures from current libraries generate a unique signature with an s-value in the lower half order.
        //
        // If your library generates malleable signatures, such as s-values in the upper range, calculate a new s-value
        // with 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141 - s1 and flip v from 27 to 28 or
        // vice versa. If your library also generates signatures with 0/1 for v instead 27/28, add 27 to v to accept
        // these malleable signatures as well.
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) {
            return (address(0), RecoverError.InvalidSignatureS, s);
        }

        // If the signature is valid (and not malleable), return the signer address
        address signer = ecrecover(hash, v, r, s);
        if (signer == address(0)) {
            return (address(0), RecoverError.InvalidSignature, bytes32(0));
        }

        return (signer, RecoverError.NoError, bytes32(0));
    }

function isValidERC1271SignatureNow(
        address signer,
        bytes32 hash,
        bytes memory signature
    ) internal view returns (bool) {
        (bool success, bytes memory result) = signer.staticcall(
            abi.encodeCall(IERC1271.isValidSignature, (hash, signature))
        );
        return (success &&
            result.length >= 32 &&
            abi.decode(result, (bytes32)) == bytes32(IERC1271.isValidSignature.selector));
    }

function createSubAccount(address userWallet)
        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        returns (address subAccount)
    {
        require(userWallet != address(0), "zero userWallet");

        address existing = _subAccountOf[userWallet];
        if (existing != address(0)) {
            return existing; // 幂等:已办卡则返回既有
        }

        bytes32 salt = _salt(userWallet);
        subAccount = address(new SubAccount{ salt: salt }(userWallet));

        _subAccountOf[userWallet] = subAccount;
        isSubAccount[subAccount] = true;
        emit SubAccountCreated(userWallet, subAccount);
    }

function _salt(address userWallet) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("HSK_PREDICT_SUBACCOUNT", userWallet));
    }

function fund(address subAccount, uint256 amount, bytes32 reason, bytes32 idemKey)
        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        nonReentrant
        whenNotPaused
    {
        _requireSubAccount(subAccount);
        require(fundLimit == 0 || amount <= fundLimit, "exceeds fund limit");
        _pay(subAccount, amount, _domain(DOMAIN_FUND, idemKey));
        emit Funded(subAccount, amount, reason, idemKey);
    }

function _requireSubAccount(address to) internal view {
        if (factory != address(0)) {
            require(ISubAccountFactory(factory).isSubAccount(to), "not a sub account");
        }
    }

function _pay(address to, uint256 amount, bytes32 idemKey) internal {
        require(to != address(0), "zero to");
        require(!used[idemKey], "idem used");
        require(address(this).balance >= amount, "insufficient treasury");
        used[idemKey] = true;
        totalPaid += amount;
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "transfer failed");
    }

function _domain(bytes32 domain, bytes32 idemKey) private pure returns (bytes32) {
        return keccak256(abi.encode(domain, idemKey));
    }

function swapExactETHForTokens(uint amountOutMin, route[] calldata routes, address to, uint deadline)
    external
    payable
    ensure(deadline)
    returns (uint[] memory amounts)
    {
        require(routes[0].from == address(weth), 'Router: INVALID_PATH');
        amounts = getAmountsOut(msg.value, routes);
        require(amounts[amounts.length - 1] >= amountOutMin, 'Router: INSUFFICIENT_OUTPUT_AMOUNT');
        weth.deposit{value: amounts[0]}();
        assert(weth.transfer(pairFor(routes[0].from, routes[0].to, routes[0].stable), amounts[0]));
        _swap(amounts, routes, to);
    }

function getAmountsOut(uint amountIn, route[] memory routes) public view returns (uint[] memory amounts) {
        require(routes.length >= 1, 'Router: INVALID_PATH');
        amounts = new uint[](routes.length+1);
        amounts[0] = amountIn;
        for (uint i = 0; i < routes.length; i++) {
            address pair = pairFor(routes[i].from, routes[i].to, routes[i].stable);
            if (IPairFactory(factory).isPair(pair)) {
                amounts[i+1] = IPair(pair).getAmountOut(amounts[i], routes[i].from);
            }
        }
    }

function pairFor(address tokenA, address tokenB, bool stable) public view returns (address pair) {
//        (address token0, address token1) = sortTokens(tokenA, tokenB);
//        pair = address(uint160(uint256(keccak256(abi.encodePacked(
//            hex'ff',
//            factory,
//            keccak256(abi.encodePacked(token0, token1, stable)),
//            pairCodeHash // init code hash
//        )))));
        pair = IPairFactory(factory).getPair(tokenA, tokenB, stable);
    }

function _swap(uint[] memory amounts, route[] memory routes, address _to) internal virtual {
        for (uint i = 0; i < routes.length; i++) {
            (address token0,) = sortTokens(routes[i].from, routes[i].to);
            uint amountOut = amounts[i + 1];
            (uint amount0Out, uint amount1Out) = routes[i].from == token0 ? (uint(0), amountOut) : (amountOut, uint(0));
            address to = i < routes.length - 1 ? pairFor(routes[i+1].from, routes[i+1].to, routes[i+1].stable) : _to;
            IPair(pairFor(routes[i].from, routes[i].to, routes[i].stable)).swap(
                amount0Out, amount1Out, to, new bytes(0)
            );
        }
    }

function isPair(address pair) external view returns (bool) {
        return IPairFactory(factory).isPair(pair);
    }

function getAmountOut(uint amountIn, address tokenIn, address tokenOut) external view returns (uint amount, bool stable) {
        address pair = pairFor(tokenIn, tokenOut, true);
        uint amountStable;
        uint amountVolatile;
        if (IPairFactory(factory).isPair(pair)) {
            amountStable = IPair(pair).getAmountOut(amountIn, tokenIn);
        }
        pair = pairFor(tokenIn, tokenOut, false);
        if (IPairFactory(factory).isPair(pair)) {
            amountVolatile = IPair(pair).getAmountOut(amountIn, tokenIn);
        }
        return amountStable > amountVolatile ? (amountStable, true) : (amountVolatile, false);
    }

function sortTokens(address tokenA, address tokenB) public pure returns (address token0, address token1) {
        require(tokenA != tokenB, 'Router: IDENTICAL_ADDRESSES');
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), 'Router: ZERO_ADDRESS');
    }

function cancelOffer(uint256 offerId)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer != msg.sender) revert NotBuyer(offerId, msg.sender);
        _deactivateOffer(offerId);
        uint256 refundAmount = offer.amount * offer.pricePerToken;
        _handleOfferFundRefund(
            offerId,
            offer.paymentToken,
            msg.sender,
            refundAmount
        );
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.CANCEL_OFFER,
            address(marketplaceVaultContract),
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferCancelled(offerId);
    }

function _deactivateOffer(uint256 offerId) internal {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) return;
        offer.active = false;
        activeOffersByToken[offer.tokenId].remove(offerId);
        activeOffersByBuyer[offer.buyer].remove(offerId);
    }

function _handleOfferFundRefund(
        uint256 offerId,
        address paymentToken,
        address buyer,
        uint256 refundAmount
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.refundOfferFundsToBuyer(
                offerId,
                buyer,
                refundAmount
            );
        } else {
            marketplaceVaultContract.refundOfferERC20FundsToBuyer(
                offerId,
                buyer,
                refundAmount,
                paymentToken
            );
        }
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

function remove(Bytes32Set storage set, bytes32 value) internal returns (bool) {
        return _remove(set._inner, value);
    }

function remove(AddressSet storage set, address value) internal returns (bool) {
        return _remove(set._inner, bytes32(uint256(uint160(value))));
    }

function remove(UintSet storage set, uint256 value) internal returns (bool) {
        return _remove(set._inner, bytes32(value));
    }

function refundOfferFundsToBuyer(
        uint256 offerId,
        address buyer,
        uint256 refundAmount
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (buyer == address(0)) revert InvalidRecipient();
        if (refundAmount == 0) revert InvalidAmount();
        if (refundAmount > address(this).balance) revert InsufficientBalance();

        payable(buyer).sendValue(refundAmount);
        emit OfferFundsRefundedToBuyer(offerId, buyer, refundAmount);
    }

function refundOfferERC20FundsToBuyer(
        uint256 offerId,
        address buyer,
        uint256 refundAmount,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (buyer == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (refundAmount == 0) revert InvalidAmount();

        // Transfer ERC20 tokens back to buyer
        IERC20(token).safeTransfer(buyer, refundAmount);

        emit OfferFundsRefundedToBuyer(offerId, buyer, refundAmount);
    }

function _recordActivity(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken
    ) internal {
        tokenActivities[tokenId].push(
            AsteroidXMarketplaceStructs.Activity({
                activityType: activityType,
                from: from,
                to: to,
                tokenId: tokenId,
                amount: amount,
                price: price,
                timestamp: block.timestamp,
                paymentToken: paymentToken
            })
        );
    }

function _recordPriceHistory(
        uint256 relatedId,
        uint256 tokenId,
        uint256 pricePerToken,
        uint256 amount,
        address seller,
        address buyer,
        address paymentToken
    ) internal returns (uint256) {
        uint256 totalValue = pricePerToken * amount;
        AsteroidXMarketplaceStructs.PriceRecord
            memory priceRecord = AsteroidXMarketplaceStructs.PriceRecord({
                listingId: relatedId,
                tokenId: tokenId,
                price: pricePerToken,
                amount: amount,
                totalValue: totalValue,
                timestamp: block.timestamp,
                seller: seller,
                buyer: buyer,
                paymentToken: paymentToken
            });
        uint256 recordIndex = priceHistories.length;
        priceHistories.push(priceRecord);
        tokenPriceHistoryIndexes[tokenId].push(recordIndex);
        emit PriceHistoryRecorded(
            tokenId,
            relatedId,
            pricePerToken,
            amount,
            totalValue,
            block.timestamp,
            seller,
            buyer,
            paymentToken
        );
        return recordIndex;
    }

function _remove(Set storage set, bytes32 value) private returns (bool) {
        // We cache the value's position to prevent multiple reads from the same storage slot
        uint256 position = set._positions[value];

        if (position != 0) {
            // Equivalent to contains(set, value)
            // To delete an element from the _values array in O(1), we swap the element to delete with the last one in
            // the array, and then remove the last element (sometimes called as 'swap and pop').
            // This modifies the order of the array, as noted in {at}.

            uint256 valueIndex = position - 1;
            uint256 lastIndex = set._values.length - 1;

            if (valueIndex != lastIndex) {
                bytes32 lastValue = set._values[lastIndex];

                // Move the lastValue to the index where the value to delete is
                set._values[valueIndex] = lastValue;
                // Update the tracked position of the lastValue (that was just moved)
                set._positions[lastValue] = position;
            }

            // Delete the slot where the moved value was stored
            set._values.pop();

            // Delete the tracked position for the deleted slot
            delete set._positions[value];

            return true;
        } else {
            return false;
        }
    }

