function batchSettle(
        uint256 eventId,
        address[] calldata subAccount,
        bytes32[] calldata outcome,
        uint256[] calldata payoutHSK
    ) external onlyRole(Roles.SETTLER_ROLE) {
        require(
            subAccount.length == outcome.length && outcome.length == payoutHSK.length,
            "length mismatch"
        );
        require(subAccount.length <= MAX_BATCH, "batch too large");
        MarketEvent storage ev = _events[eventId];
        require(ev.status == EventStatus.Settled, "not settled");
        for (uint256 i = 0; i < subAccount.length; i++) {
            require(!settled[eventId][subAccount[i]][outcome[i]], "position settled");

            // **派付金额必须由持仓约束**。原实现 `payoutHSK` 完全由调用方指定、
            // `subAccount` 也不校验身份,于是持 SETTLER_ROLE 的热钥匙可以
            // 「开事件 → 结算 → 按金库全额派付给自己」直接清库。
            //
            // 每份获胜份额兑 1 HSK,链上份额与金额同为 18 位精度,故合法上限恰为持仓数。
            // 作废(resultType=1)退的是成本,成本必然小于份额×1 HSK(价格 1–99¢),
            // 所以同一个上限对两种结算都成立。
            uint256 held = positions[subAccount[i]][eventId][outcome[i]];
            // **读获胜集合而不是单值字段**:一个事件可以有多个赢家。
            // 护栏本身没变——没在获胜集合里的仍然必须拿零。
            if (ev.resultType == 0 && !isWinning[eventId][outcome[i]]) {
                require(payoutHSK[i] == 0, "loser must be paid zero");
            }
            require(payoutHSK[i] <= held, "payout exceeds position");
            // 事件级守恒：出池不得超过进池。定价在链下,合约判断不了价格是否公允,
            // 但这条不需要知道价格——撮合出任何差错,金库在本事件上的净支出都不为正
            paid[eventId] += payoutHSK[i];
            require(paid[eventId] <= collected[eventId], "payout exceeds collected");
            outstanding -= payoutHSK[i];

            settled[eventId][subAccount[i]][outcome[i]] = true;
            positions[subAccount[i]][eventId][outcome[i]] = 0;
            if (payoutHSK[i] > 0) {
                treasury.payout(
                    subAccount[i],
                    payoutHSK[i],
                    "SETTLE",
                    keccak256(abi.encode("SETTLE", eventId, subAccount[i], outcome[i]))
                );
            }
            emit SettlementPaid(eventId, subAccount[i], outcome[i], payoutHSK[i]);
        }
    }

function cancelOffer(uint256 offerId)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer != msg.sender) revert NotBuyer(offerId, msg.sender);
        _deactivateOffer(offerId);
        uint256 refundAmount = offer.amount * offer.pricePerToken;
        _handleOfferFundRefund(
            offerId,
            offer.paymentToken,
            msg.sender,
            refundAmount
        );
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.CANCEL_OFFER,
            address(marketplaceVaultContract),
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferCancelled(offerId);
    }

function _deactivateOffer(uint256 offerId) internal {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) return;
        offer.active = false;
        activeOffersByToken[offer.tokenId].remove(offerId);
        activeOffersByBuyer[offer.buyer].remove(offerId);
    }

function _handleOfferFundRefund(
        uint256 offerId,
        address paymentToken,
        address buyer,
        uint256 refundAmount
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.refundOfferFundsToBuyer(
                offerId,
                buyer,
                refundAmount
            );
        } else {
            marketplaceVaultContract.refundOfferERC20FundsToBuyer(
                offerId,
                buyer,
                refundAmount,
                paymentToken
            );
        }
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

