function refundOfferFundsToBuyer(
        uint256 offerId,
        address buyer,
        uint256 refundAmount
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (buyer == address(0)) revert InvalidRecipient();
        if (refundAmount == 0) revert InvalidAmount();
        if (refundAmount > address(this).balance) revert InsufficientBalance();

        payable(buyer).sendValue(refundAmount);
        emit OfferFundsRefundedToBuyer(offerId, buyer, refundAmount);
    }

function refundOfferERC20FundsToBuyer(
        uint256 offerId,
        address buyer,
        uint256 refundAmount,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (buyer == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (refundAmount == 0) revert InvalidAmount();

        // Transfer ERC20 tokens back to buyer
        IERC20(token).safeTransfer(buyer, refundAmount);

        emit OfferFundsRefundedToBuyer(offerId, buyer, refundAmount);
    }

function _recordActivity(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken
    ) internal {
        tokenActivities[tokenId].push(
            AsteroidXMarketplaceStructs.Activity({
                activityType: activityType,
                from: from,
                to: to,
                tokenId: tokenId,
                amount: amount,
                price: price,
                timestamp: block.timestamp,
                paymentToken: paymentToken
            })
        );
    }

function _recordPriceHistory(
        uint256 relatedId,
        uint256 tokenId,
        uint256 pricePerToken,
        uint256 amount,
        address seller,
        address buyer,
        address paymentToken
    ) internal returns (uint256) {
        uint256 totalValue = pricePerToken * amount;
        AsteroidXMarketplaceStructs.PriceRecord
            memory priceRecord = AsteroidXMarketplaceStructs.PriceRecord({
                listingId: relatedId,
                tokenId: tokenId,
                price: pricePerToken,
                amount: amount,
                totalValue: totalValue,
                timestamp: block.timestamp,
                seller: seller,
                buyer: buyer,
                paymentToken: paymentToken
            });
        uint256 recordIndex = priceHistories.length;
        priceHistories.push(priceRecord);
        tokenPriceHistoryIndexes[tokenId].push(recordIndex);
        emit PriceHistoryRecorded(
            tokenId,
            relatedId,
            pricePerToken,
            amount,
            totalValue,
            block.timestamp,
            seller,
            buyer,
            paymentToken
        );
        return recordIndex;
    }

function _remove(Set storage set, bytes32 value) private returns (bool) {
        // We cache the value's position to prevent multiple reads from the same storage slot
        uint256 position = set._positions[value];

        if (position != 0) {
            // Equivalent to contains(set, value)
            // To delete an element from the _values array in O(1), we swap the element to delete with the last one in
            // the array, and then remove the last element (sometimes called as 'swap and pop').
            // This modifies the order of the array, as noted in {at}.

            uint256 valueIndex = position - 1;
            uint256 lastIndex = set._values.length - 1;

            if (valueIndex != lastIndex) {
                bytes32 lastValue = set._values[lastIndex];

                // Move the lastValue to the index where the value to delete is
                set._values[valueIndex] = lastValue;
                // Update the tracked position of the lastValue (that was just moved)
                set._positions[lastValue] = position;
            }

            // Delete the slot where the moved value was stored
            set._values.pop();

            // Delete the tracked position for the deleted slot
            delete set._positions[value];

            return true;
        } else {
            return false;
        }
    }

function lock(uint256 ruleId) public nonReentrant {
        require(!isPausingForOperation, "Contract is pausing for operation.");
        LockRule memory ruleInfo = lockRules[ruleId];
        require(ruleInfo.isValid, "Staking is invalid.");
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "No more supply.");

        uint256 LOCK_AMOUNT = ruleInfo.lockAmount;
        uint256 fee = LOCK_AMOUNT * FEE_RATE / 10000;
        uint256 lockAmount = LOCK_AMOUNT - fee;
        bool feeSuccess = tokenATT.transferFrom(msg.sender, FEE_HOLDER, fee);
        require(feeSuccess, "Token transfer failed");
        bool lockSuccess = tokenATT.transferFrom(msg.sender, address(this), lockAmount);
        require(lockSuccess, "Token transfer failed");

        // Save user info
        userCurrentLockedId[msg.sender] += 1;
        userLockInfo[msg.sender][userCurrentLockedId[msg.sender]] = LockInfo(
            ruleId, msg.sender, userCurrentLockedId[msg.sender],
            lockAmount, block.timestamp, UNLOCK_DURATION,
            block.timestamp + UNLOCK_DURATION, ruleInfo.rewardsAmount, false
        );

        // Send rewards
        SUPPLY_LIMIT -= ruleInfo.rewardsAmount;
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "Insufficient supply limit.");
        (bool rewardSuccess, ) = payable(msg.sender).call{value: ruleInfo.rewardsAmount}("");
        require(rewardSuccess, "Rewards failed");


        emit Lock(msg.sender, ruleId, lockAmount, block.timestamp);
    }

function createPool(
        address tokenA,
        address tokenB,
        uint24 fee
    ) external override noDelegateCall returns (address pool) {
        require(tokenA != tokenB);
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0));
        int24 tickSpacing = feeAmountTickSpacing[fee];
        require(tickSpacing != 0);
        require(getPool[token0][token1][fee] == address(0));
        pool = deploy(address(this), token0, token1, fee, tickSpacing);
        getPool[token0][token1][fee] = pool;
        // populate mapping in the reverse direction, deliberate choice to avoid the cost of comparing addresses
        getPool[token1][token0][fee] = pool;
        emit PoolCreated(token0, token1, fee, tickSpacing, pool);
    }

function deploy(
        address factory,
        address token0,
        address token1,
        uint24 fee,
        int24 tickSpacing
    ) internal returns (address pool) {
        parameters = Parameters({factory: factory, token0: token0, token1: token1, fee: fee, tickSpacing: tickSpacing});
        pool = address(new HyperindexV3Pool{salt: keccak256(abi.encode(token0, token1, fee))}());
        delete parameters;
    }

function withdraw(uint256 amount) public {
        require(balanceOf(msg.sender) >= amount, "WHSK: Insufficient balance");
        _burn(msg.sender, amount);
        payable(msg.sender).transfer(amount);
        emit Withdrawal(msg.sender, amount);
    }

function balanceOf(address account) public view virtual override returns (uint256) {
        return _balances[account];
    }

function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        uint256 accountBalance = _balances[account];
        require(accountBalance >= amount, "ERC20: burn amount exceeds balance");
        unchecked {
            _balances[account] = accountBalance - amount;
            // Overflow not possible: amount <= accountBalance <= totalSupply.
            _totalSupply -= amount;
        }

        emit Transfer(account, address(0), amount);

        _afterTokenTransfer(account, address(0), amount);
    }

function transfer(address to, uint256 amount) public virtual override returns (bool) {
        address owner = _msgSender();
        _transfer(owner, to, amount);
        return true;
    }

function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual {}

function _afterTokenTransfer(address from, address to, uint256 amount) internal virtual {}

function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }

function _transfer(address from, address to, uint256 amount) internal virtual {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");

        _beforeTokenTransfer(from, to, amount);

        uint256 fromBalance = _balances[from];
        require(fromBalance >= amount, "ERC20: transfer amount exceeds balance");
        unchecked {
            _balances[from] = fromBalance - amount;
            // Overflow not possible: the sum of all balances is capped by totalSupply, and the sum is preserved by
            // decrementing then incrementing.
            _balances[to] += amount;
        }

        emit Transfer(from, to, amount);

        _afterTokenTransfer(from, to, amount);
    }

