function supplyLiquidity(uint256 _amount, address _user) public onlyLendingPool whenNotPaused nonReentrant returns (uint256 shares) {
        if (_amount == 0) revert ZeroAmount();
        accrueInterest();
        shares = 0;
        if (totalSupplyAssets == 0) {
            if (_amount < _minAmountSupplyLiquidity()) revert MinAmountSupplyLiquidity(_amount, _minAmountSupplyLiquidity());
            shares = _amount;
        } else {
            shares = _amount * _totalSupplyShares() / totalSupplyAssets;
        }
        // Reject dust deposits that would mint 0 shares (the deposit would otherwise be absorbed for free).
        if (shares == 0) revert ZeroShares();
        totalSupplyAssets += _amount;

        uint256 mintToShares = shares * 10 ** _sharesTokenDecimals() / 10 ** _underlyingDecimals();
        IPaboxoSharesToken(sharesToken).mint(_user, mintToShares);

        return shares;
    }

function supplyLiquidity(address _user, uint256 _amount) public payable whenNotPaused nonReentrant {
        uint256 shares = _supplyLiquidity(_amount, _user);
        _supplyLiquidityTransfer(_amount);
        emit SupplyLiquidity(_user, _amount, shares);
    }

