function fund(address subAccount, uint256 amount, bytes32 reason, bytes32 idemKey)
        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        nonReentrant
        whenNotPaused
    {
        _requireSubAccount(subAccount);
        require(fundLimit == 0 || amount <= fundLimit, "exceeds fund limit");
        _pay(subAccount, amount, _domain(DOMAIN_FUND, idemKey));
        emit Funded(subAccount, amount, reason, idemKey);
    }

function _requireSubAccount(address to) internal view {
        if (factory != address(0)) {
            require(ISubAccountFactory(factory).isSubAccount(to), "not a sub account");
        }
    }

function _pay(address to, uint256 amount, bytes32 idemKey) internal {
        require(to != address(0), "zero to");
        require(!used[idemKey], "idem used");
        require(address(this).balance >= amount, "insufficient treasury");
        used[idemKey] = true;
        totalPaid += amount;
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "transfer failed");
    }

function _domain(bytes32 domain, bytes32 idemKey) private pure returns (bytes32) {
        return keccak256(abi.encode(domain, idemKey));
    }

function fund(address subAccount, uint256 amount, bytes32 reason, bytes32 idemKey)
        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        nonReentrant
        whenNotPaused
    {
        _requireSubAccount(subAccount);
        require(fundLimit == 0 || amount <= fundLimit, "exceeds fund limit");
        _pay(subAccount, amount, _domain(DOMAIN_FUND, idemKey));
        emit Funded(subAccount, amount, reason, idemKey);
    }

function _requireSubAccount(address to) internal view {
        if (factory != address(0)) {
            require(ISubAccountFactory(factory).isSubAccount(to), "not a sub account");
        }
    }

function _pay(address to, uint256 amount, bytes32 idemKey) internal {
        require(to != address(0), "zero to");
        require(!used[idemKey], "idem used");
        require(address(this).balance >= amount, "insufficient treasury");
        used[idemKey] = true;
        totalPaid += amount;
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "transfer failed");
    }

function _domain(bytes32 domain, bytes32 idemKey) private pure returns (bytes32) {
        return keccak256(abi.encode(domain, idemKey));
    }

function confirmMerge(
        bytes32 matchId,
        address subA,
        address subB,
        uint256 eventId,
        bytes32 outcomeA,
        bytes32 outcomeB,
        uint256 shares,
        uint256 aGetsHSK
    ) external onlyRole(Roles.MATCHER_ROLE) {
        require(!matchProcessed[matchId], "match processed");
        require(_events[eventId].status == EventStatus.Live, "event not live");
        require(shares > 0, "zero shares");
        require(outcomeA != outcomeB, "same side");
        // **销毁的两条腿同样必须是同一档的正反面**（与 `confirmMatch` 同一条口径）。
        // 销毁会 `_release` 掉 1 HSK/份并付给两人；两条腿若不是一对，
        // 放走的就是别人那一份的钱——两档各自的对手腿还在，索赔一分没少，
        // 事件从此结算不了。校验放在改余额之前。
        require(complement[eventId][outcomeA] == outcomeB, "legs not complementary");
        require(aGetsHSK <= shares, "split exceeds shares");
        require(positions[subA][eventId][outcomeA] >= shares, "insufficient shares");
        require(positions[subB][eventId][outcomeB] >= shares, "insufficient shares");

        matchProcessed[matchId] = true;
        positions[subA][eventId][outcomeA] -= shares;
        positions[subB][eventId][outcomeB] -= shares;
        _release(eventId, shares);
        totalCostLocked -= shares;

        uint256 bGetsHSK = shares - aGetsHSK;
        if (aGetsHSK > 0) {
            treasury.payout(subA, aGetsHSK, "MERGE", keccak256(abi.encode("MRGA", matchId)));
        }
        if (bGetsHSK > 0) {
            treasury.payout(subB, bGetsHSK, "MERGE", keccak256(abi.encode("MRGB", matchId)));
        }
        emit PositionsMerged(matchId, subA, subB, eventId, shares, aGetsHSK);
    }

function _release(uint256 eventId, uint256 amount) private {
        require(collected[eventId] >= amount, "release exceeds collected");
        collected[eventId] -= amount;
        outstanding -= amount;
    }

function setL1BlockValuesEcotone() public {
        _setL1BlockValuesEcotone();
    }

function _setL1BlockValuesEcotone() internal {
        address depositor = DEPOSITOR_ACCOUNT();
        assembly {
            // Revert if the caller is not the depositor account.
            if xor(caller(), depositor) {
                mstore(0x00, 0x3cc50b45) // 0x3cc50b45 is the 4-byte selector of "NotDepositor()"
                revert(0x1C, 0x04) // returns the stored 4-byte selector from above
            }
            // sequencenum (uint64), blobBaseFeeScalar (uint32), baseFeeScalar (uint32)
            sstore(sequenceNumber.slot, shr(128, calldataload(4)))
            // number (uint64) and timestamp (uint64)
            sstore(number.slot, shr(128, calldataload(20)))
            sstore(basefee.slot, calldataload(36)) // uint256
            sstore(blobBaseFee.slot, calldataload(68)) // uint256
            sstore(hash.slot, calldataload(100)) // bytes32
            sstore(batcherHash.slot, calldataload(132)) // bytes32
        }
    }

