function fund(address subAccount, uint256 amount, bytes32 reason, bytes32 idemKey)
        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        nonReentrant
        whenNotPaused
    {
        _requireSubAccount(subAccount);
        require(fundLimit == 0 || amount <= fundLimit, "exceeds fund limit");
        _pay(subAccount, amount, _domain(DOMAIN_FUND, idemKey));
        emit Funded(subAccount, amount, reason, idemKey);
    }

function _requireSubAccount(address to) internal view {
        if (factory != address(0)) {
            require(ISubAccountFactory(factory).isSubAccount(to), "not a sub account");
        }
    }

function _pay(address to, uint256 amount, bytes32 idemKey) internal {
        require(to != address(0), "zero to");
        require(!used[idemKey], "idem used");
        require(address(this).balance >= amount, "insufficient treasury");
        used[idemKey] = true;
        totalPaid += amount;
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "transfer failed");
    }

function _domain(bytes32 domain, bytes32 idemKey) private pure returns (bytes32) {
        return keccak256(abi.encode(domain, idemKey));
    }

function depositWithPermit(
        bytes32 orderRef,
        address buyer,
        address seller,
        uint256 amount,
        uint64 deliveryDeadline,
        uint256 authDeadline,
        bytes calldata authSig,
        uint256 permitDeadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant {
        Deal storage deal = _deals[orderRef];
        if (deal.state != State.None) revert InvalidState(deal.state);
        if (amount == 0 || amount > type(uint96).max) revert InvalidAmount();
        if (buyer == address(0) || seller == address(0) || seller == buyer) revert InvalidAddress();
        if (deliveryDeadline <= block.timestamp) revert DeliveryDeadlinePassed();
        if (block.timestamp > authDeadline) revert SignatureExpired();

        _verifyDepositAuthorization(orderRef, buyer, seller, amount, deliveryDeadline, authDeadline, authSig);

        deal.buyer = buyer;
        deal.amount = uint96(amount);
        deal.seller = seller;
        deal.deliveryDeadline = deliveryDeadline;
        deal.state = State.Funded;

        emit Deposited(orderRef, buyer, seller, amount, deliveryDeadline);

        try IERC20Permit(token).permit(buyer, address(this), amount, permitDeadline, v, r, s) {} catch {}
        IERC20(token).safeTransferFrom(buyer, address(this), amount);
    }

function _verifyDepositAuthorization(
        bytes32 orderRef,
        address buyer,
        address seller,
        uint256 amount,
        uint64 deliveryDeadline,
        uint256 authDeadline,
        bytes calldata authSig
    ) private view {
        bytes32 structHash = keccak256(
            abi.encode(DEPOSIT_AUTHORIZATION_TYPEHASH, orderRef, seller, amount, deliveryDeadline, authDeadline)
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        if (!SignatureChecker.isValidSignatureNow(buyer, digest, authSig)) revert InvalidSignature();
    }

function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

function _hashTypedDataV4(bytes32 structHash) internal view virtual returns (bytes32) {
        return MessageHashUtils.toTypedDataHash(_domainSeparatorV4(), structHash);
    }

function isValidSignatureNow(address signer, bytes32 hash, bytes memory signature) internal view returns (bool) {
        if (signer.code.length == 0) {
            (address recovered, ECDSA.RecoverError err, ) = ECDSA.tryRecover(hash, signature);
            return err == ECDSA.RecoverError.NoError && recovered == signer;
        } else {
            return isValidERC1271SignatureNow(signer, hash, signature);
        }
    }

function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

function toTypedDataHash(bytes32 domainSeparator, bytes32 structHash) internal pure returns (bytes32 digest) {
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, hex"19_01")
            mstore(add(ptr, 0x02), domainSeparator)
            mstore(add(ptr, 0x22), structHash)
            digest := keccak256(ptr, 0x42)
        }
    }

function _domainSeparatorV4() internal view returns (bytes32) {
        if (address(this) == _cachedThis && block.chainid == _cachedChainId) {
            return _cachedDomainSeparator;
        } else {
            return _buildDomainSeparator();
        }
    }

function tryRecover(
        bytes32 hash,
        bytes memory signature
    ) internal pure returns (address recovered, RecoverError err, bytes32 errArg) {
        if (signature.length == 65) {
            bytes32 r;
            bytes32 s;
            uint8 v;
            // ecrecover takes the signature parameters, and the only way to get them
            // currently is to use assembly.
            assembly ("memory-safe") {
                r := mload(add(signature, 0x20))
                s := mload(add(signature, 0x40))
                v := byte(0, mload(add(signature, 0x60)))
            }
            return tryRecover(hash, v, r, s);
        } else {
            return (address(0), RecoverError.InvalidSignatureLength, bytes32(signature.length));
        }
    }

function tryRecover(
        bytes32 hash,
        bytes32 r,
        bytes32 vs
    ) internal pure returns (address recovered, RecoverError err, bytes32 errArg) {
        unchecked {
            bytes32 s = vs & bytes32(0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff);
            // We do not check for an overflow here since the shift operation results in 0 or 1.
            uint8 v = uint8((uint256(vs) >> 255) + 27);
            return tryRecover(hash, v, r, s);
        }
    }

function tryRecover(
        bytes32 hash,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) internal pure returns (address recovered, RecoverError err, bytes32 errArg) {
        // EIP-2 still allows signature malleability for ecrecover(). Remove this possibility and make the signature
        // unique. Appendix F in the Ethereum Yellow paper (https://ethereum.github.io/yellowpaper/paper.pdf), defines
        // the valid range for s in (301): 0 < s < secp256k1n ÷ 2 + 1, and for v in (302): v ∈ {27, 28}. Most
        // signatures from current libraries generate a unique signature with an s-value in the lower half order.
        //
        // If your library generates malleable signatures, such as s-values in the upper range, calculate a new s-value
        // with 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141 - s1 and flip v from 27 to 28 or
        // vice versa. If your library also generates signatures with 0/1 for v instead 27/28, add 27 to v to accept
        // these malleable signatures as well.
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) {
            return (address(0), RecoverError.InvalidSignatureS, s);
        }

        // If the signature is valid (and not malleable), return the signer address
        address signer = ecrecover(hash, v, r, s);
        if (signer == address(0)) {
            return (address(0), RecoverError.InvalidSignature, bytes32(0));
        }

        return (signer, RecoverError.NoError, bytes32(0));
    }

function isValidERC1271SignatureNow(
        address signer,
        bytes32 hash,
        bytes memory signature
    ) internal view returns (bool) {
        (bool success, bytes memory result) = signer.staticcall(
            abi.encodeCall(IERC1271.isValidSignature, (hash, signature))
        );
        return (success &&
            result.length >= 32 &&
            abi.decode(result, (bytes32)) == bytes32(IERC1271.isValidSignature.selector));
    }

function stake(
        uint256 lockPeriod
    ) external 
        payable 
        nonReentrant 
        whenNotPaused 
        notBlacklisted 
        whitelistCheck
        whenNotEmergency  // Add emergency mode check
        returns (uint256) 
    {
        require(block.timestamp < stakeEndTime, "Staking period has ended");

        // Add validation for lockPeriod
        StakingLib.validateAndGetRate(
            lockPeriod, 
            lockOptions,
            historicalRates
        );

        uint256 amount = msg.value;
        amount = StakingLib.validateAndFormatAmount(amount, minStakeAmount);

        if (totalStaked + amount > maxTotalStake) revert MaxTotalStakeExceeded();

        // Calculate potential reward for this new stake
        uint256 rewardRate = StakingLib.validateAndGetRate(
            lockPeriod, 
            lockOptions,
            historicalRates
        );
        uint256 potentialReward = StakingLib.calculateReward(
            amount,
            lockPeriod,  // timeElapsed
