        uint256 protocolCut = (royaltyAmount * PROTOCOL_CUT) / RATIO_BASE;
        userTokenRoyaltyBalance[beneficiary][reserveToken] +=
            royaltyAmount -
            protocolCut;
        userTokenRoyaltyBalance[protocolBeneficiary][
            reserveToken
        ] += protocolCut;
    }

