function stakeLocked(StakeType _stakeType) external payable nonReentrant whenNotPaused {
        // Strict validation of minimum stake amount
        require(msg.value >= minStakeAmount, "Amount below minimum stake");
        require(block.timestamp < stakeEndTime, "Staking ended");

        // Update reward pool
        updateRewardPool();

        // Calculate shares to mint
        uint256 sharesAmount = getSharesForHSK(msg.value);

        require(sharesAmount > 0, "Shares amount cannot be zero");

        if (!initialLiquidityMinted) {
            require(sharesAmount >= MINIMUM_LIQUIDITY, "Initial stake too small");
            initialLiquidityMinted = true;
            stHSK.mint(0x000000000000000000000000000000000000dEaD, MINIMUM_LIQUIDITY);
            sharesAmount -= MINIMUM_LIQUIDITY;
        }

        // Determine lock period
        uint256 lockDuration;
        if (_stakeType == StakeType.FIXED_30_DAYS) lockDuration = 30 days;
        else if (_stakeType == StakeType.FIXED_90_DAYS) lockDuration = 90 days;
        else if (_stakeType == StakeType.FIXED_180_DAYS) lockDuration = 180 days;
        else if (_stakeType == StakeType.FIXED_365_DAYS) lockDuration = 365 days;
        else revert("Invalid stake type");

        // Create locked stake record
        lockedStakes[msg.sender].push(LockedStake({
            sharesAmount: sharesAmount,
            hskAmount: msg.value,
            lockEndTime: block.timestamp + lockDuration,
            lockDuration: lockDuration,
            withdrawn: false
        }));

        // Update total staked amount
        totalPooledHSK += msg.value;

        // 更新该锁定期类型的质押总量
        totalSharesByStakeType[_stakeType] += sharesAmount;

        // Mint stHSK tokens
        stHSK.mint(msg.sender, sharesAmount);

        uint256 stakeId = lockedStakes[msg.sender].length - 1;
        emit Stake(msg.sender, msg.value, sharesAmount, _stakeType, block.timestamp + lockDuration, stakeId);
    }

function updateRewardPool() public {
        if (block.number <= lastRewardBlock) {
            return;
        }

        if (totalPooledHSK == 0) {
            lastRewardBlock = block.number;
            return;
        }

        uint256 multiplier = block.number - lastRewardBlock;
        uint256 hskReward = multiplier * hskPerBlock;

        // Calculate and limit APR using configurable block time
        // SECONDS_PER_YEAR is 365 days (31,536,000 seconds)
        // Explicitly calculate blocks per year based on the configured block time
        uint256 blocksPerYear = SECONDS_PER_YEAR / blockTime;  // 31,536,000 / blockTime
        uint256 annualReward = hskPerBlock * blocksPerYear;
        uint256 currentAPR = (annualReward * BASIS_POINTS) / totalPooledHSK;
        if (currentAPR > MAX_APR) {
            hskReward = (totalPooledHSK * MAX_APR * multiplier) / (BASIS_POINTS * blocksPerYear);
        }

        // 计算额外的锁定期奖励
        uint256 additionalBonusRewards = 0;

        // 获取总shares数量
        uint256 totalShares = stHSK.totalSupply();

        if (totalShares > 0) {
            // 计算每种锁定期类型的额外奖励
            uint256 bonusReward30Days = 0;
            uint256 bonusReward90Days = 0;
            uint256 bonusReward180Days = 0;
            uint256 bonusReward365Days = 0;

            // 只有当该类型有质押时才计算奖励
            if (totalSharesByStakeType[StakeType.FIXED_30_DAYS] > 0) {
                // 计算该类型质押占总质押的比例
                uint256 shareRatio30Days = (totalSharesByStakeType[StakeType.FIXED_30_DAYS] * PRECISION_FACTOR) / totalShares;
                // 计算该类型的基础奖励
                uint256 baseReward30Days = (hskReward * shareRatio30Days) / PRECISION_FACTOR;
                // 计算该类型的额外奖励
                bonusReward30Days = (baseReward30Days * stakingBonus[StakeType.FIXED_30_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_90_DAYS] > 0) {
                uint256 shareRatio90Days = (totalSharesByStakeType[StakeType.FIXED_90_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward90Days = (hskReward * shareRatio90Days) / PRECISION_FACTOR;
                bonusReward90Days = (baseReward90Days * stakingBonus[StakeType.FIXED_90_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_180_DAYS] > 0) {
                uint256 shareRatio180Days = (totalSharesByStakeType[StakeType.FIXED_180_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward180Days = (hskReward * shareRatio180Days) / PRECISION_FACTOR;
                bonusReward180Days = (baseReward180Days * stakingBonus[StakeType.FIXED_180_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_365_DAYS] > 0) {
                uint256 shareRatio365Days = (totalSharesByStakeType[StakeType.FIXED_365_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward365Days = (hskReward * shareRatio365Days) / PRECISION_FACTOR;
                bonusReward365Days = (baseReward365Days * stakingBonus[StakeType.FIXED_365_DAYS]) / BASIS_POINTS;
            }

            // 计算总的额外奖励
            additionalBonusRewards = bonusReward30Days + bonusReward90Days + bonusReward180Days + bonusReward365Days;
        }

        // 总奖励 = 基础奖励 + 额外的锁定期奖励
        uint256 totalReward = hskReward + additionalBonusRewards;

        // Check if contract has enough HSK
        if (reservedRewards >= totalReward) {
            totalPooledHSK += totalReward;
            reservedRewards -= totalReward;

            // Update exchange rate
            emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
        } else {
            if (reservedRewards > 0) {
                totalPooledHSK += reservedRewards;
                totalReward = reservedRewards;
                reservedRewards = 0;

                // Update exchange rate
                emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
            }
            emit InsufficientRewards(totalReward, reservedRewards);
        }

        lastRewardBlock = block.number;
    }

function getSharesForHSK(uint256 _hskAmount) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();

        // Initial 1:1 exchange rate
        if (totalShares == 0 || totalPooledHSK == 0) {
            return _hskAmount;
        }

        // 计算实际的总份额（减去最小流动性）
        uint256 effectiveTotalShares = totalShares;
        if (initialLiquidityMinted) {
            effectiveTotalShares = totalShares - MINIMUM_LIQUIDITY;
        }

        // 计算实际的总质押HSK（减去最小流动性对应的HSK）
        uint256 effectiveTotalPooledHSK = totalPooledHSK;
        if (initialLiquidityMinted) {
            effectiveTotalPooledHSK = totalPooledHSK - MINIMUM_LIQUIDITY;
        }

        // Calculate shares based on the current pool ratio
        return (_hskAmount * effectiveTotalShares) / effectiveTotalPooledHSK;
    }

function mint(address to, uint256 sharesAmount) external onlyOwner {
        _mint(to, sharesAmount);
    }

function totalSupply() public view virtual returns (uint256) {
        return _totalSupply;
    }

function getHSKForShares(uint256 _sharesAmount) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        return (_sharesAmount * totalPooledHSK) / totalShares;
    }

function _mint(address account, uint256 value) internal {
        if (account == address(0)) {
            revert ERC20InvalidReceiver(address(0));
        }
        _update(address(0), account, value);
    }

function _update(address from, address to, uint256 value) internal virtual {
        if (from == address(0)) {
            // Overflow check required: The rest of the code assumes that totalSupply never overflows
            _totalSupply += value;
        } else {
            uint256 fromBalance = _balances[from];
            if (fromBalance < value) {
                revert ERC20InsufficientBalance(from, fromBalance, value);
            }
            unchecked {
                // Overflow not possible: value <= fromBalance <= totalSupply.
                _balances[from] = fromBalance - value;
            }
        }

        if (to == address(0)) {
            unchecked {
                // Overflow not possible: value <= totalSupply or value <= fromBalance <= totalSupply.
                _totalSupply -= value;
            }
        } else {
            unchecked {
                // Overflow not possible: balance + value is at most totalSupply, which we know fits into a uint256.
                _balances[to] += value;
            }
        }

        emit Transfer(from, to, value);
    }

function verifyOracleProofV2(bytes calldata _bytesProof) external returns (PriceInfo memory) {
        OracleProofV2 memory oracle = abi.decode(_bytesProof, (OracleProofV2));
        uint256 paircnt = 0;
        for (uint256 i; i < oracle.data.length; ++i) {
            paircnt += oracle.data[i].committee_data.committee_feeds.length;
            if (merkleSet.contains(oracle.data[i].root)) {
                continue;
            }
            requireRootVerified(oracle.data[i].root, oracle.data[i].sigs, oracle.data[i].committee_id);
            if (!merkleSet.set(oracle.data[i].root)) {
                revert RootIsZero();
            }
        }

        uint256[] memory updateMask = new uint256[](paircnt);

        PriceInfo memory priceData = PriceInfo(
            new uint256[](paircnt),
            new uint256[](paircnt),
            new uint256[](paircnt),
            new uint256[](paircnt),
            new uint256[](paircnt)
        );

        uint256 pair_map = 0;
        uint256 maxFutureTimestamp = block.timestamp * MILLISECOND_CONVERSION_FACTOR + TIME_DELTA_ALLOWANCE;

        for (uint256 a = 0; a < oracle.data.length;) {
            verifyMultileafMerkleProof(oracle.data[a].committee_data, oracle.data[a].root);
            for (uint256 b = 0; b < oracle.data[a].committee_data.committee_feeds.length;) {
                priceData.pairs[pair_map] = oracle.data[a].committee_data.committee_feeds[b].pair;

                uint256 lastRound =
                                    supraSValueFeedStorage.getRound(uint256(oracle.data[a].committee_data.committee_feeds[b].pair));

                if (
                    oracle.data[a].committee_data.committee_feeds[b].round > lastRound
                    && oracle.data[a].committee_data.committee_feeds[b].round <= maxFutureTimestamp
                ) {
                    packData(
                        oracle.data[a].committee_data.committee_feeds[b].pair,
                        oracle.data[a].committee_data.committee_feeds[b].round,
                        oracle.data[a].committee_data.committee_feeds[b].decimals,
                        oracle.data[a].committee_data.committee_feeds[b].timestamp,
                        oracle.data[a].committee_data.committee_feeds[b].price
                    );
                    priceData.prices[pair_map] = oracle.data[a].committee_data.committee_feeds[b].price;
                    priceData.round[pair_map] = oracle.data[a].committee_data.committee_feeds[b].round;
                    priceData.timestamp[pair_map] = oracle.data[a].committee_data.committee_feeds[b].timestamp;
                    priceData.decimal[pair_map] = oracle.data[a].committee_data.committee_feeds[b].decimals;
                    updateMask[pair_map] = 1;
                } else if (oracle.data[a].committee_data.committee_feeds[b].round > maxFutureTimestamp) {
                    revert IncorrectFutureUpdate(
                        oracle.data[a].committee_data.committee_feeds[b].round - block.timestamp * MILLISECOND_CONVERSION_FACTOR
                    );
                } else if (oracle.data[a].committee_data.committee_feeds[b].round < lastRound) {
                    ISupraSValueFeed.priceFeed memory value =
                                        supraSValueFeedStorage.getSvalue(uint256(oracle.data[a].committee_data.committee_feeds[b].pair));
                    priceData.prices[pair_map] = value.price;
                    priceData.round[pair_map] = lastRound;
                    priceData.timestamp[pair_map] = value.time;
                    priceData.decimal[pair_map] = value.decimals;
                    updateMask[pair_map] = 0;
                } else {
                    priceData.prices[pair_map] = oracle.data[a].committee_data.committee_feeds[b].price;
                    priceData.round[pair_map] = oracle.data[a].committee_data.committee_feeds[b].round;
                    priceData.timestamp[pair_map] = oracle.data[a].committee_data.committee_feeds[b].timestamp;
                    priceData.decimal[pair_map] = oracle.data[a].committee_data.committee_feeds[b].decimals;
                    updateMask[pair_map] = 0;
                }

                unchecked {
                    ++b;
                    ++pair_map;
                }
            }

            unchecked {
                ++a;
            }
        }

        emit PriceUpdate(priceData.pairs, priceData.prices, updateMask);
        return priceData;
    }

