function createListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) external nonReentrant whenNotPaused whenFunctionNotPaused withVaultCheck {
        _validateListing(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        _transferNFT(
            msg.sender,
            address(marketplaceVaultContract),
            tokenId,
            amount,
            false
        );
        uint256 listingId = _nextListingId++;
        listings[listingId] = AsteroidXMarketplaceStructs.Listing({
            listingId: listingId,
            seller: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeListingsByToken[tokenId].add(listingId);
        activeListingsBySeller[msg.sender].add(listingId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.LISTING,
            msg.sender,
            address(0),
            amount,
            pricePerToken,
            paymentToken,
            listingId
        );
        emit ListingCreated(
            listingId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidAmount(amount, MAX_AMOUNT_PER_LISTING);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidPrice(pricePerToken, MAX_PRICE_PER_TOKEN);
        if (expirationTime <= block.timestamp)
            revert ListingExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
        if (
            IERC1155(address(asteroidXToken)).balanceOf(msg.sender, tokenId) <
            amount
        ) revert InsufficientTokenBalance(tokenId, amount);
        if (
            !IERC1155(address(asteroidXToken)).isApprovedForAll(
                msg.sender,
                address(this)
            )
        ) revert MarketplaceNotApproved();
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                address(marketplaceVaultContract),
                tokenId,
                amount,
                ""
            );
            marketplaceVaultContract.transferNFTToBuyer(
                address(asteroidXToken),
                tokenId,
                amount,
                to
            );
        } else {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                to,
                tokenId,
                amount,
                ""
            );
        }
    }

function add(Bytes32Set storage set, bytes32 value) internal returns (bool) {
        return _add(set._inner, value);
    }

function add(AddressSet storage set, address value) internal returns (bool) {
        return _add(set._inner, bytes32(uint256(uint160(value))));
    }

function add(UintSet storage set, uint256 value) internal returns (bool) {
        return _add(set._inner, bytes32(value));
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

function contains(Bytes32Set storage set, bytes32 value) internal view returns (bool) {
        return _contains(set._inner, value);
    }

function contains(AddressSet storage set, address value) internal view returns (bool) {
        return _contains(set._inner, bytes32(uint256(uint160(value))));
    }

function contains(UintSet storage set, uint256 value) internal view returns (bool) {
        return _contains(set._inner, bytes32(value));
    }

function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

function transferNFTToBuyer(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (buyer == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            buyer,
            tokenId,
            amount,
            ""
        );
        emit NFTTransferredToBuyer(tokenContract, tokenId, amount, buyer);
    }

function purchaseListing(uint256 listingId, uint256 amount)
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) revert ListingNotActive(listingId);
        if (block.timestamp >= listing.expirationTime)
            revert ListingExpired(listingId, listing.expirationTime);
        if (amount == 0 || amount > listing.amount)
            revert InvalidAmount(amount, listing.amount);
        if (msg.sender == listing.seller) revert CannotBuyOwnListing();

        uint256 totalPrice = amount * listing.pricePerToken;
        listing.amount -= amount;
        if (listing.amount == 0) {
            _deactivateListing(listingId);
        }
        marketplaceVaultContract.transferNFTToBuyer(
            address(asteroidXToken),
            listing.tokenId,
            amount,
            msg.sender
        );
        _handlePaymentWithFees(
            listing.paymentToken,
            msg.sender,
            listing.seller,
            totalPrice,
            msg.value,
            listing.paymentToken
        );
        _recordTransaction(
            listing.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.SALE,
            listing.seller,
            msg.sender,
            amount,
            listing.pricePerToken,
            listing.paymentToken,
            listingId
        );
        emit ListingSold(
            listingId,
            msg.sender,
            listing.tokenId,
            amount,
            totalPrice,
            block.timestamp,
            listing.paymentToken
        );
    }

function _deactivateListing(uint256 listingId) internal {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) return;
        listing.active = false;
        activeListingsByToken[listing.tokenId].remove(listingId);
        activeListingsBySeller[listing.seller].remove(listingId);
    }

