function _recordPriceHistory(
        uint256 relatedId,
        uint256 tokenId,
        uint256 pricePerToken,
        uint256 amount,
        address seller,
        address buyer,
        address paymentToken
    ) internal returns (uint256) {
        uint256 totalValue = pricePerToken * amount;
        AsteroidXMarketplaceStructs.PriceRecord
            memory priceRecord = AsteroidXMarketplaceStructs.PriceRecord({
                listingId: relatedId,
                tokenId: tokenId,
                price: pricePerToken,
                amount: amount,
                totalValue: totalValue,
                timestamp: block.timestamp,
                seller: seller,
                buyer: buyer,
                paymentToken: paymentToken
            });
        uint256 recordIndex = priceHistories.length;
        priceHistories.push(priceRecord);
        tokenPriceHistoryIndexes[tokenId].push(recordIndex);
        emit PriceHistoryRecorded(
            tokenId,
            relatedId,
            pricePerToken,
            amount,
            totalValue,
            block.timestamp,
            seller,
            buyer,
            paymentToken
        );
        return recordIndex;
    }

function _remove(Set storage set, bytes32 value) private returns (bool) {
        // We cache the value's position to prevent multiple reads from the same storage slot
        uint256 position = set._positions[value];

        if (position != 0) {
            // Equivalent to contains(set, value)
            // To delete an element from the _values array in O(1), we swap the element to delete with the last one in
            // the array, and then remove the last element (sometimes called as 'swap and pop').
            // This modifies the order of the array, as noted in {at}.

            uint256 valueIndex = position - 1;
            uint256 lastIndex = set._values.length - 1;

            if (valueIndex != lastIndex) {
                bytes32 lastValue = set._values[lastIndex];

                // Move the lastValue to the index where the value to delete is
                set._values[valueIndex] = lastValue;
                // Update the tracked position of the lastValue (that was just moved)
                set._positions[lastValue] = position;
            }

            // Delete the slot where the moved value was stored
            set._values.pop();

            // Delete the tracked position for the deleted slot
            delete set._positions[value];

            return true;
        } else {
            return false;
        }
    }

function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

function acceptOffer(uint256 offerId)
        external
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer == msg.sender) revert CannotAcceptOwnOffer();
        if (block.timestamp >= offer.expirationTime)
            revert OfferExpired(offerId, offer.expirationTime);

        IERC1155AsteroidX token = asteroidXToken;
        if (token.balanceOf(msg.sender, offer.tokenId) < offer.amount)
            revert InsufficientTokenBalance(offer.tokenId, offer.amount);

        uint256 totalOfferValue = offer.amount * offer.pricePerToken;
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalOfferValue,
            offer.paymentToken
        );

        _transferNFT(
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            true
        );
        _handleOfferFundWithdrawal(
            offerId,
            offer.paymentToken,
            msg.sender,
            feeRecipient,
            sellerProceeds,
            platformFee
        );
        _deactivateOffer(offerId);
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER,
            msg.sender,
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferAccepted(
            offerId,
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            totalOfferValue,
            block.timestamp,
            offer.paymentToken
        );
    }

function _calculateFees(uint256 totalAmount, address paymentToken)
        internal
        view
        returns (uint256 platformFee, uint256 sellerProceeds)
    {
        uint256 feeRateToUse = paymentTokenFeeRates[paymentToken];
        platformFee = (feeRateToUse > 0 && totalAmount > 0)
            ? Math.mulDiv(totalAmount, feeRateToUse, 10000)
            : 0;
        sellerProceeds = totalAmount - platformFee;
        return (platformFee, sellerProceeds);
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                address(marketplaceVaultContract),
                tokenId,
                amount,
                ""
            );
            marketplaceVaultContract.transferNFTToBuyer(
                address(asteroidXToken),
                tokenId,
                amount,
                to
            );
        } else {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                to,
                tokenId,
                amount,
                ""
            );
        }
    }

function _handleOfferFundWithdrawal(
        uint256 offerId,
        address paymentToken,
        address seller,
        address feeRecipientAddress,
        uint256 sellerProceeds,
        uint256 platformFee
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.withdrawOfferFundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee
            );
        } else {
            marketplaceVaultContract.withdrawOfferERC20FundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee,
                paymentToken
            );
        }
    }

function _deactivateOffer(uint256 offerId) internal {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) return;
        offer.active = false;
        activeOffersByToken[offer.tokenId].remove(offerId);
        activeOffersByBuyer[offer.buyer].remove(offerId);
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
