function createListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) external nonReentrant whenNotPaused whenFunctionNotPaused withVaultCheck {
        _validateListing(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        _transferNFT(
            msg.sender,
            address(marketplaceVaultContract),
            tokenId,
            amount,
            false
        );
        uint256 listingId = _nextListingId++;
        listings[listingId] = AsteroidXMarketplaceStructs.Listing({
            listingId: listingId,
            seller: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeListingsByToken[tokenId].add(listingId);
        activeListingsBySeller[msg.sender].add(listingId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.LISTING,
            msg.sender,
            address(0),
            amount,
            pricePerToken,
            paymentToken,
            listingId
        );
        emit ListingCreated(
            listingId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidAmount(amount, MAX_AMOUNT_PER_LISTING);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidPrice(pricePerToken, MAX_PRICE_PER_TOKEN);
        if (expirationTime <= block.timestamp)
            revert ListingExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
        if (
            IERC1155(address(asteroidXToken)).balanceOf(msg.sender, tokenId) <
            amount
        ) revert InsufficientTokenBalance(tokenId, amount);
        if (
            !IERC1155(address(asteroidXToken)).isApprovedForAll(
                msg.sender,
                address(this)
            )
        ) revert MarketplaceNotApproved();
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
