function confirmMatch(
        bytes32 matchId,
        address takerSub,
        address makerSub,
        uint256 eventId,
        bytes32 takerOutcome,
        bytes32 makerOutcome,
        uint256 shares,
        uint256 takerPaysHSK
    ) external onlyRole(Roles.MATCHER_ROLE) {
        require(!matchProcessed[matchId], "match processed");
        require(_events[eventId].status == EventStatus.Live, "event not live");
        require(shares > 0, "zero shares");
        require(takerOutcome != makerOutcome, "same side");
        // **两条腿必须是同一档的正反面**。只校验「不相等」的话，
        // 「>80 的是」能和「>90 的否」撮成一笔——两档可同时成立，
        // 于是两边都该拿钱而池里只有一份的钱，事件永久结算不了。
        require(complement[eventId][takerOutcome] == makerOutcome, "legs not complementary");
        require(takerPaysHSK <= shares, "cost exceeds shares");

        matchProcessed[matchId] = true;
        uint256 makerPaysHSK = shares - takerPaysHSK;

        if (takerPaysHSK > 0) ISubAccount(takerSub).payToTreasury(takerPaysHSK);
        if (makerPaysHSK > 0) ISubAccount(makerSub).payToTreasury(makerPaysHSK);

        totalCostLocked += shares;
        _commit(eventId, shares);
        positions[takerSub][eventId][takerOutcome] += shares;
        positions[makerSub][eventId][makerOutcome] += shares;

        emit MatchConfirmed(
            matchId, takerSub, makerSub, eventId, takerOutcome, makerOutcome, shares, takerPaysHSK
        );
    }

function _commit(uint256 eventId, uint256 amount) private {
        collected[eventId] += amount;
        outstanding += amount;
        require(address(treasury).balance >= outstanding, "treasury cannot back this");
    }

function purchaseListing(uint256 listingId, uint256 amount)
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) revert ListingNotActive(listingId);
        if (block.timestamp >= listing.expirationTime)
            revert ListingExpired(listingId, listing.expirationTime);
        if (amount == 0 || amount > listing.amount)
            revert InvalidAmount(amount, listing.amount);
        if (msg.sender == listing.seller) revert CannotBuyOwnListing();

        uint256 totalPrice = amount * listing.pricePerToken;
        listing.amount -= amount;
        if (listing.amount == 0) {
            _deactivateListing(listingId);
        }
        marketplaceVaultContract.transferNFTToBuyer(
            address(asteroidXToken),
            listing.tokenId,
            amount,
            msg.sender
        );
        _handlePaymentWithFees(
            listing.paymentToken,
            msg.sender,
            listing.seller,
            totalPrice,
            msg.value,
            listing.paymentToken
        );
        _recordTransaction(
            listing.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.SALE,
            listing.seller,
            msg.sender,
            amount,
            listing.pricePerToken,
            listing.paymentToken,
            listingId
        );
        emit ListingSold(
            listingId,
            msg.sender,
            listing.tokenId,
            amount,
            totalPrice,
            block.timestamp,
            listing.paymentToken
        );
    }

