        }
    }

function acceptOffer(uint256 offerId)
        external
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer == msg.sender) revert CannotAcceptOwnOffer();
        if (block.timestamp >= offer.expirationTime)
            revert OfferExpired(offerId, offer.expirationTime);

        IERC1155AsteroidX token = asteroidXToken;
        if (token.balanceOf(msg.sender, offer.tokenId) < offer.amount)
            revert InsufficientTokenBalance(offer.tokenId, offer.amount);

        uint256 totalOfferValue = offer.amount * offer.pricePerToken;
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalOfferValue,
            offer.paymentToken
        );

        _transferNFT(
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            true
        );
        _handleOfferFundWithdrawal(
            offerId,
            offer.paymentToken,
            msg.sender,
            feeRecipient,
            sellerProceeds,
            platformFee
        );
        _deactivateOffer(offerId);
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER,
            msg.sender,
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferAccepted(
            offerId,
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            totalOfferValue,
            block.timestamp,
            offer.paymentToken
        );
    }

function _calculateFees(uint256 totalAmount, address paymentToken)
        internal
        view
        returns (uint256 platformFee, uint256 sellerProceeds)
    {
        uint256 feeRateToUse = paymentTokenFeeRates[paymentToken];
        platformFee = (feeRateToUse > 0 && totalAmount > 0)
            ? Math.mulDiv(totalAmount, feeRateToUse, 10000)
            : 0;
        sellerProceeds = totalAmount - platformFee;
        return (platformFee, sellerProceeds);
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                address(marketplaceVaultContract),
                tokenId,
                amount,
                ""
            );
            marketplaceVaultContract.transferNFTToBuyer(
                address(asteroidXToken),
                tokenId,
                amount,
                to
            );
        } else {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                to,
                tokenId,
                amount,
                ""
            );
        }
    }

function _handleOfferFundWithdrawal(
        uint256 offerId,
        address paymentToken,
        address seller,
        address feeRecipientAddress,
        uint256 sellerProceeds,
        uint256 platformFee
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.withdrawOfferFundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee
            );
        } else {
            marketplaceVaultContract.withdrawOfferERC20FundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee,
                paymentToken
            );
        }
    }

function _deactivateOffer(uint256 offerId) internal {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) return;
        offer.active = false;
        activeOffersByToken[offer.tokenId].remove(offerId);
        activeOffersByBuyer[offer.buyer].remove(offerId);
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

function mulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 result) {
        unchecked {
            (uint256 high, uint256 low) = mul512(x, y);

            // Handle non-overflow cases, 256 by 256 division.
            if (high == 0) {
                // Solidity will revert if denominator == 0, unlike the div opcode on its own.
                // The surrounding unchecked block does not change this fact.
                // See https://docs.soliditylang.org/en/latest/control-structures.html#checked-or-unchecked-arithmetic.
                return low / denominator;
            }

            // Make sure the result is less than 2²⁵⁶. Also prevents denominator == 0.
            if (denominator <= high) {
                Panic.panic(ternary(denominator == 0, Panic.DIVISION_BY_ZERO, Panic.UNDER_OVERFLOW));
            }

            ///////////////////////////////////////////////
            // 512 by 256 division.
            ///////////////////////////////////////////////

            // Make division exact by subtracting the remainder from [high low].
            uint256 remainder;
            assembly ("memory-safe") {
                // Compute remainder using mulmod.
                remainder := mulmod(x, y, denominator)

                // Subtract 256 bit number from 512 bit number.
                high := sub(high, gt(remainder, low))
                low := sub(low, remainder)
            }

            // Factor powers of two out of denominator and compute largest power of two divisor of denominator.
            // Always >= 1. See https://cs.stackexchange.com/q/138556/92363.

            uint256 twos = denominator & (0 - denominator);
            assembly ("memory-safe") {
                // Divide denominator by twos.
                denominator := div(denominator, twos)

                // Divide [high low] by twos.
                low := div(low, twos)

                // Flip twos such that it is 2²⁵⁶ / twos. If twos is zero, then it becomes one.
                twos := add(div(sub(0, twos), twos), 1)
            }

            // Shift in bits from high into low.
            low |= high * twos;

            // Invert denominator mod 2²⁵⁶. Now that denominator is an odd number, it has an inverse modulo 2²⁵⁶ such
            // that denominator * inv ≡ 1 mod 2²⁵⁶. Compute the inverse by starting with a seed that is correct for
            // four bits. That is, denominator * inv ≡ 1 mod 2⁴.
            uint256 inverse = (3 * denominator) ^ 2;

            // Use the Newton-Raphson iteration to improve the precision. Thanks to Hensel's lifting lemma, this also
            // works in modular arithmetic, doubling the correct bits in each step.
            inverse *= 2 - denominator * inverse; // inverse mod 2⁸
            inverse *= 2 - denominator * inverse; // inverse mod 2¹⁶
            inverse *= 2 - denominator * inverse; // inverse mod 2³²
            inverse *= 2 - denominator * inverse; // inverse mod 2⁶⁴
            inverse *= 2 - denominator * inverse; // inverse mod 2¹²⁸
            inverse *= 2 - denominator * inverse; // inverse mod 2²⁵⁶

            // Because the division is now exact we can divide by multiplying with the modular inverse of denominator.
            // This will give us the correct result modulo 2²⁵⁶. Since the preconditions guarantee that the outcome is
            // less than 2²⁵⁶, this is the final result. We don't need to compute the high bits of the result and high
            // is no longer required.
            result = low * inverse;
            return result;
        }
    }

function mulDiv(uint256 x, uint256 y, uint256 denominator, Rounding rounding) internal pure returns (uint256) {
        return mulDiv(x, y, denominator) + SafeCast.toUint(unsignedRoundsUp(rounding) && mulmod(x, y, denominator) > 0);
    }

function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

function transferNFTToBuyer(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (buyer == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            buyer,
            tokenId,
            amount,
            ""
        );
        emit NFTTransferredToBuyer(tokenContract, tokenId, amount, buyer);
    }

function withdrawOfferFundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        uint256 totalAmount = sellerProceeds + platformFee;
        if (totalAmount > address(this).balance) revert InsufficientBalance();

        // First transfer to seller
        payable(seller).sendValue(sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            payable(platformFeeRecipient).sendValue(platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function withdrawOfferERC20FundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        // Get the ERC20 token contract
        IERC20 erc20Token = IERC20(token);

        // First transfer to seller
        erc20Token.safeTransfer(seller, sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            erc20Token.safeTransfer(platformFeeRecipient, platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

function execute(bytes calldata commands, bytes[] calldata inputs, uint256 deadline)
        external
        payable
        checkDeadline(deadline)
    {
        execute(commands, inputs);
    }

function execute(bytes calldata commands, bytes[] calldata inputs) public payable override isNotLocked {
        bool success;
        bytes memory output;
        uint256 numCommands = commands.length;
        if (inputs.length != numCommands) revert LengthMismatch();

        // loop through all given commands, execute them and pass along outputs as defined
        for (uint256 commandIndex = 0; commandIndex < numCommands; commandIndex++) {
            bytes1 command = commands[commandIndex];

            bytes calldata input = inputs[commandIndex];

            (success, output) = dispatch(command, input);

            if (!success && successRequired(command)) {
                revert ExecutionFailed({commandIndex: commandIndex, message: output});
            }
        }
    }

function dispatch(bytes1 commandType, bytes calldata inputs) internal returns (bool success, bytes memory output) {
        uint256 command = uint8(commandType & Commands.COMMAND_TYPE_MASK);

        success = true;

        // 0x00 <= command < 0x21
        if (command < Commands.EXECUTE_SUB_PLAN) {
            // 0x00 <= command < 0x10
            if (command < Commands.V4_SWAP) {
                // 0x00 <= command < 0x08
                if (command < Commands.V2_SWAP_EXACT_IN) {
                    if (command == Commands.V3_SWAP_EXACT_IN) {
                        // equivalent: abi.decode(inputs, (address, uint256, uint256, bytes, bool))
                        address recipient;
                        uint256 amountIn;
                        uint256 amountOutMin;
                        bool payerIsUser;
                        assembly {
                            recipient := calldataload(inputs.offset)
                            amountIn := calldataload(add(inputs.offset, 0x20))
                            amountOutMin := calldataload(add(inputs.offset, 0x40))
                            // 0x60 offset is the path, decoded below
                            payerIsUser := calldataload(add(inputs.offset, 0x80))
                        }
                        bytes calldata path = inputs.toBytes(3);
                        address payer = payerIsUser ? msgSender() : address(this);
                        v3SwapExactInput(map(recipient), amountIn, amountOutMin, path, payer);
                    } else if (command == Commands.V3_SWAP_EXACT_OUT) {
                        // equivalent: abi.decode(inputs, (address, uint256, uint256, bytes, bool))
                        address recipient;
                        uint256 amountOut;
                        uint256 amountInMax;
                        bool payerIsUser;
                        assembly {
                            recipient := calldataload(inputs.offset)
                            amountOut := calldataload(add(inputs.offset, 0x20))
                            amountInMax := calldataload(add(inputs.offset, 0x40))
                            // 0x60 offset is the path, decoded below
                            payerIsUser := calldataload(add(inputs.offset, 0x80))
                        }
                        bytes calldata path = inputs.toBytes(3);
                        address payer = payerIsUser ? msgSender() : address(this);
                        v3SwapExactOutput(map(recipient), amountOut, amountInMax, path, payer);
                    } else if (command == Commands.PERMIT2_TRANSFER_FROM) {
                        // equivalent: abi.decode(inputs, (address, address, uint160))
                        address token;
                        address recipient;
                        uint160 amount;
                        assembly {
                            token := calldataload(inputs.offset)
                            recipient := calldataload(add(inputs.offset, 0x20))
                            amount := calldataload(add(inputs.offset, 0x40))
                        }
                        permit2TransferFrom(token, msgSender(), map(recipient), amount);
                    } else if (command == Commands.PERMIT2_PERMIT_BATCH) {
                        IAllowanceTransfer.PermitBatch calldata permitBatch;
                        assembly {
                            // this is a variable length struct, so calldataload(inputs.offset) contains the
                            // offset from inputs.offset at which the struct begins
                            permitBatch := add(inputs.offset, calldataload(inputs.offset))
                        }
                        bytes calldata data = inputs.toBytes(1);
                        (success, output) = address(PERMIT2)
                            .call(
                                abi.encodeWithSignature(
                                    'permit(address,((address,uint160,uint48,uint48)[],address,uint256),bytes)',
                                    msgSender(),
                                    permitBatch,
                                    data
                                )
                            );
                    } else if (command == Commands.SWEEP) {
                        // equivalent:  abi.decode(inputs, (address, address, uint256))
                        address token;
                        address recipient;
                        uint160 amountMin;
                        assembly {
                            token := calldataload(inputs.offset)
                            recipient := calldataload(add(inputs.offset, 0x20))
                            amountMin := calldataload(add(inputs.offset, 0x40))
                        }
                        Payments.sweep(token, map(recipient), amountMin);
                    } else if (command == Commands.TRANSFER) {
                        // equivalent:  abi.decode(inputs, (address, address, uint256))
                        address token;
                        address recipient;
                        uint256 value;
                        assembly {
                            token := calldataload(inputs.offset)
                            recipient := calldataload(add(inputs.offset, 0x20))
                            value := calldataload(add(inputs.offset, 0x40))
                        }
                        Payments.pay(token, map(recipient), value);
                    } else if (command == Commands.PAY_PORTION) {
                        // equivalent:  abi.decode(inputs, (address, address, uint256))
                        address token;
                        address recipient;
                        uint256 bips;
                        assembly {
                            token := calldataload(inputs.offset)
                            recipient := calldataload(add(inputs.offset, 0x20))
                            bips := calldataload(add(inputs.offset, 0x40))
                        }
                        Payments.payPortion(token, map(recipient), bips);
                    } else {
                        // placeholder area for command 0x07
                        revert InvalidCommandType(command);
                    }
                } else {
                    // 0x08 <= command < 0x10
                    if (command == Commands.V2_SWAP_EXACT_IN) {
                        // equivalent: abi.decode(inputs, (address, uint256, uint256, bytes, bool))
                        address recipient;
                        uint256 amountIn;
                        uint256 amountOutMin;
                        bool payerIsUser;
                        assembly {
                            recipient := calldataload(inputs.offset)
                            amountIn := calldataload(add(inputs.offset, 0x20))
                            amountOutMin := calldataload(add(inputs.offset, 0x40))
                            // 0x60 offset is the path, decoded below
                            payerIsUser := calldataload(add(inputs.offset, 0x80))
                        }
                        address[] calldata path = inputs.toAddressArray(3);
                        address payer = payerIsUser ? msgSender() : address(this);
                        v2SwapExactInput(map(recipient), amountIn, amountOutMin, path, payer);
                    } else if (command == Commands.V2_SWAP_EXACT_OUT) {
                        // equivalent: abi.decode(inputs, (address, uint256, uint256, bytes, bool))
                        address recipient;
                        uint256 amountOut;
                        uint256 amountInMax;
                        bool payerIsUser;
                        assembly {
                            recipient := calldataload(inputs.offset)
                            amountOut := calldataload(add(inputs.offset, 0x20))
                            amountInMax := calldataload(add(inputs.offset, 0x40))
                            // 0x60 offset is the path, decoded below
                            payerIsUser := calldataload(add(inputs.offset, 0x80))
                        }
                        address[] calldata path = inputs.toAddressArray(3);
                        address payer = payerIsUser ? msgSender() : address(this);
                        v2SwapExactOutput(map(recipient), amountOut, amountInMax, path, payer);
                    } else if (command == Commands.PERMIT2_PERMIT) {
                        // equivalent: abi.decode(inputs, (IAllowanceTransfer.PermitSingle, bytes))
                        IAllowanceTransfer.PermitSingle calldata permitSingle;
                        assembly {
                            permitSingle := inputs.offset
                        }
                        bytes calldata data = inputs.toBytes(6); // PermitSingle takes first 6 slots (0..5)
                        (success, output) = address(PERMIT2)
                            .call(
                                abi.encodeWithSignature(
                                    'permit(address,((address,uint160,uint48,uint48),address,uint256),bytes)',
                                    msgSender(),
                                    permitSingle,
                                    data
                                )
                            );
                    } else if (command == Commands.WRAP_ETH) {
                        // equivalent: abi.decode(inputs, (address, uint256))
                        address recipient;
                        uint256 amount;
                        assembly {
                            recipient := calldataload(inputs.offset)
                            amount := calldataload(add(inputs.offset, 0x20))
                        }
                        Payments.wrapETH(map(recipient), amount);
                    } else if (command == Commands.UNWRAP_WETH) {
                        // equivalent: abi.decode(inputs, (address, uint256))
                        address recipient;
                        uint256 amountMin;
                        assembly {
                            recipient := calldataload(inputs.offset)
                            amountMin := calldataload(add(inputs.offset, 0x20))
                        }
                        Payments.unwrapWETH9(map(recipient), amountMin);
                    } else if (command == Commands.PERMIT2_TRANSFER_FROM_BATCH) {
                        IAllowanceTransfer.AllowanceTransferDetails[] calldata batchDetails;
                        (uint256 length, uint256 offset) = inputs.toLengthOffset(0);
                        assembly {
                            batchDetails.length := length
                            batchDetails.offset := offset
                        }
                        permit2TransferFrom(batchDetails, msgSender());
                    } else if (command == Commands.BALANCE_CHECK_ERC20) {
                        // equivalent: abi.decode(inputs, (address, address, uint256))
                        address owner;
                        address token;
                        uint256 minBalance;
                        assembly {
                            owner := calldataload(inputs.offset)
                            token := calldataload(add(inputs.offset, 0x20))
                            minBalance := calldataload(add(inputs.offset, 0x40))
                        }
                        success = (ERC20(token).balanceOf(owner) >= minBalance);
                        if (!success) output = abi.encodePacked(BalanceTooLow.selector);
                    } else {
                        // placeholder area for command 0x0f
                        revert InvalidCommandType(command);
                    }
                }
            } else {
                // 0x10 <= command < 0x21
                if (command == Commands.V4_SWAP) {
                    // pass the calldata provided to V4SwapRouter._executeActions (defined in BaseActionsRouter)
                    _executeActions(inputs);
                    // This contract MUST be approved to spend the token since its going to be doing the call on the position manager
                } else if (command == Commands.V3_POSITION_MANAGER_PERMIT) {
                    _checkV3PermitCall(inputs);
                    (success, output) = address(V3_POSITION_MANAGER).call(inputs);
                } else if (command == Commands.V3_POSITION_MANAGER_CALL) {
                    _checkV3PositionManagerCall(inputs, msgSender());
                    (success, output) = address(V3_POSITION_MANAGER).call(inputs);
                } else if (command == Commands.V4_INITIALIZE_POOL) {
                    PoolKey calldata poolKey;
                    uint160 sqrtPriceX96;
                    assembly {
                        poolKey := inputs.offset
                        sqrtPriceX96 := calldataload(add(inputs.offset, 0xa0))
                    }
                    (success, output) =
                        address(poolManager).call(abi.encodeCall(IPoolManager.initialize, (poolKey, sqrtPriceX96)));
                } else if (command == Commands.V4_POSITION_MANAGER_CALL) {
                    // should only call modifyLiquidities() to mint
                    _checkV4PositionManagerCall(inputs);
                    (success, output) = address(V4_POSITION_MANAGER).call{value: address(this).balance}(inputs);
                } else {
                    // placeholder area for commands 0x15-0x20
                    revert InvalidCommandType(command);
                }
            }
        } else if (command < Commands.ACROSS_V4_DEPOSIT_V3) {
            // 0x21 <= command
            if (command == Commands.EXECUTE_SUB_PLAN) {
                (bytes calldata _commands, bytes[] calldata _inputs) = inputs.decodeCommandsAndInputs();
                (success, output) = (address(this)).call(abi.encodeCall(Dispatcher.execute, (_commands, _inputs)));
            } else {
                // placeholder area for commands 0x22-0x3f
                revert InvalidCommandType(command);
            }
        } else {
            if (command == Commands.ACROSS_V4_DEPOSIT_V3) {
                _acrossV4DepositV3(inputs);
            } else {
                // placeholder area for commands 0x41-0x5f
                revert InvalidCommandType(command);
            }
        }
    }

function successRequired(bytes1 command) internal pure returns (bool) {
        return command & Commands.FLAG_ALLOW_REVERT == 0;
    }

function add(BalanceDelta a, BalanceDelta b) pure returns (BalanceDelta) {
    int256 res0;
    int256 res1;
    assembly ("memory-safe") {
        let a0 := sar(128, a)
        let a1 := signextend(15, a)
        let b0 := sar(128, b)
        let b1 := signextend(15, b)
        res0 := add(a0, b0)
        res1 := add(a1, b1)
    }
    return toBalanceDelta(res0.toInt128(), res1.toInt128());
}

function toBytes(bytes calldata _bytes, uint256 _arg) internal pure returns (bytes calldata res) {
        uint256 length;
        assembly ("memory-safe") {
            // The offset of the `_arg`-th element is `32 * arg`, which stores the offset of the length pointer.
            // shl(5, x) is equivalent to mul(32, x)
            let lengthPtr :=
                add(_bytes.offset, and(calldataload(add(_bytes.offset, shl(5, _arg))), OFFSET_OR_LENGTH_MASK))
            // the number of bytes in the bytes string
            length := and(calldataload(lengthPtr), OFFSET_OR_LENGTH_MASK)
            // the offset where the bytes string begins
            let offset := add(lengthPtr, 0x20)
            // assign the return parameters
            res.length := length
            res.offset := offset

            // if the provided bytes string isnt as long as the encoding says, revert
            if lt(add(_bytes.length, _bytes.offset), add(length, offset)) {
                mstore(0, SLICE_ERROR_SELECTOR)
                revert(0x1c, 4)
            }
        }
    }

