    uint256 tokenId,
    address auth
  ) internal override(ERC721Enumerable) returns (address) {
    return super._update(to, tokenId, auth);
  }

function _update(address to, uint256 tokenId, address auth) internal virtual returns (address) {
        address from = _ownerOf(tokenId);

        // Perform (optional) operator check
        if (auth != address(0)) {
            _checkAuthorized(from, auth, tokenId);
        }

        // Execute the update
        if (from != address(0)) {
            // Clear approval. No need to re-authorize or emit the Approval event
            _approve(address(0), tokenId, address(0), false);

            unchecked {
                _balances[from] -= 1;
            }
        }

        if (to != address(0)) {
            unchecked {
                _balances[to] += 1;
            }
        }

        _owners[tokenId] = to;

        emit Transfer(from, to, tokenId);

        return from;
    }

function _update(address to, uint256 tokenId, address auth) internal virtual override returns (address) {
        address previousOwner = super._update(to, tokenId, auth);

        if (previousOwner == address(0)) {
            _addTokenToAllTokensEnumeration(tokenId);
        } else if (previousOwner != to) {
            _removeTokenFromOwnerEnumeration(previousOwner, tokenId);
        }
        if (to == address(0)) {
            _removeTokenFromAllTokensEnumeration(tokenId);
        } else if (previousOwner != to) {
            _addTokenToOwnerEnumeration(to, tokenId);
        }

        return previousOwner;
    }

function _ownerOf(uint256 tokenId) internal view virtual returns (address) {
        return _owners[tokenId];
    }

function _checkAuthorized(address owner, address spender, uint256 tokenId) internal view virtual {
        if (!_isAuthorized(owner, spender, tokenId)) {
            if (owner == address(0)) {
                revert ERC721NonexistentToken(tokenId);
            } else {
                revert ERC721InsufficientApproval(spender, tokenId);
            }
        }
    }

function batchCancelListings(uint256[] calldata listingIds)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        uint256 canceledCount = 0;
        for (uint256 i = 0; i < listingIds.length; i++) {
            AsteroidXMarketplaceStructs.Listing storage listing = listings[
                listingIds[i]
            ];
            if (listing.seller != msg.sender)
                revert NotSeller(listingIds[i], msg.sender);
            if (listing.active) {
                _deactivateListing(listingIds[i]);
                marketplaceVaultContract.returnNFTToSeller(
                    address(asteroidXToken),
                    listing.tokenId,
                    listing.amount,
                    listing.seller
                );
                _recordTransaction(
                    listing.tokenId,
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING,
                    msg.sender,
                    address(0),
                    listing.amount,
                    0,
                    listing.paymentToken,
                    listingIds[i]
                );
                emit ListingCancelled(listingIds[i]);
                canceledCount++;
            }
        }
        if (canceledCount > 0) {
            emit BatchOperation(
                uint256(
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING
                ),
                canceledCount
            );
        }
    }

