function _remove(Set storage set, bytes32 value) private returns (bool) {
        // We cache the value's position to prevent multiple reads from the same storage slot
        uint256 position = set._positions[value];

        if (position != 0) {
            // Equivalent to contains(set, value)
            // To delete an element from the _values array in O(1), we swap the element to delete with the last one in
            // the array, and then remove the last element (sometimes called as 'swap and pop').
            // This modifies the order of the array, as noted in {at}.

            uint256 valueIndex = position - 1;
            uint256 lastIndex = set._values.length - 1;

            if (valueIndex != lastIndex) {
                bytes32 lastValue = set._values[lastIndex];

                // Move the lastValue to the index where the value to delete is
                set._values[valueIndex] = lastValue;
                // Update the tracked position of the lastValue (that was just moved)
                set._positions[lastValue] = position;
            }

            // Delete the slot where the moved value was stored
            set._values.pop();

            // Delete the tracked position for the deleted slot
            delete set._positions[value];

            return true;
        } else {
            return false;
        }
    }

function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

function createListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) external nonReentrant whenNotPaused whenFunctionNotPaused withVaultCheck {
        _validateListing(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        _transferNFT(
            msg.sender,
            address(marketplaceVaultContract),
            tokenId,
            amount,
            false
        );
        uint256 listingId = _nextListingId++;
        listings[listingId] = AsteroidXMarketplaceStructs.Listing({
            listingId: listingId,
            seller: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeListingsByToken[tokenId].add(listingId);
        activeListingsBySeller[msg.sender].add(listingId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.LISTING,
            msg.sender,
            address(0),
            amount,
            pricePerToken,
            paymentToken,
            listingId
        );
        emit ListingCreated(
            listingId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidAmount(amount, MAX_AMOUNT_PER_LISTING);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidPrice(pricePerToken, MAX_PRICE_PER_TOKEN);
        if (expirationTime <= block.timestamp)
            revert ListingExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
        if (
            IERC1155(address(asteroidXToken)).balanceOf(msg.sender, tokenId) <
            amount
        ) revert InsufficientTokenBalance(tokenId, amount);
        if (
            !IERC1155(address(asteroidXToken)).isApprovedForAll(
                msg.sender,
                address(this)
            )
        ) revert MarketplaceNotApproved();
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                address(marketplaceVaultContract),
                tokenId,
                amount,
                ""
            );
            marketplaceVaultContract.transferNFTToBuyer(
                address(asteroidXToken),
                tokenId,
                amount,
                to
            );
        } else {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                to,
                tokenId,
                amount,
                ""
            );
        }
    }

