function getHSKForSharesByType(uint256 _sharesAmount, StakeType stakeType) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        if (totalSharesByStakeType[stakeType] == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        uint256 totalRewards = hskPerBlock * (block.number - startBlock);
        uint256 unClaimedRewards = totalRewards - totalPaidRewards;

        uint256 ratio = calculateCorrectionFactor(stakeType);
        //  reward 不能超 最大 APR
        uint256 reward = _sharesAmount * unClaimedRewards * ratio / (totalSharesByStakeType[stakeType] * BASIS_POINTS);
        uint256 base =  (_sharesAmount * totalPooledHSK) / totalShares;
        uint256 maxReward = _sharesAmount * maxAPRs[stakeType] / BASIS_POINTS;
        if (reward > maxReward) {
            reward = maxReward;
        }
        return reward + base;
    }

function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        uint256 accountBalance = _balances[account];
        require(accountBalance >= amount, "ERC20: burn amount exceeds balance");
        unchecked {
            _balances[account] = accountBalance - amount;
            // Overflow not possible: amount <= accountBalance <= totalSupply.
            _totalSupply -= amount;
        }

        emit Transfer(account, address(0), amount);

        _afterTokenTransfer(account, address(0), amount);
    }

function calculateCorrectionFactor(StakeType stakeType) public view returns (uint256) {
        // 计算所有池的总加权质押量
        uint256 totalWeightedShares = 0;
        for (uint256 i = 0; i < 5; i++) {
            StakeType currentType = StakeType(i);
            totalWeightedShares += maxAPRs[currentType] * totalSharesByStakeType[currentType];
        }
        // 避免除以零
        if (totalWeightedShares == 0) {
            return 1;
        }

        // 计算指定池的加权质押量
        uint256 weightedShares = maxAPRs[stakeType] * totalSharesByStakeType[stakeType];

        // 计算占总质押的百分比
        uint256 percentOfTotalShares = totalSharesByStakeType[stakeType] * BASIS_POINTS / totalWeightedShares;

        // 如果百分比为0，避免除以零
        if (percentOfTotalShares == 0) {
            return (weightedShares * BASIS_POINTS) / totalWeightedShares;
        }

        return (weightedShares * BASIS_POINTS) / totalWeightedShares;
    }

function createListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) external nonReentrant whenNotPaused whenFunctionNotPaused withVaultCheck {
        _validateListing(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        _transferNFT(
            msg.sender,
            address(marketplaceVaultContract),
            tokenId,
            amount,
            false
        );
        uint256 listingId = _nextListingId++;
        listings[listingId] = AsteroidXMarketplaceStructs.Listing({
            listingId: listingId,
            seller: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeListingsByToken[tokenId].add(listingId);
        activeListingsBySeller[msg.sender].add(listingId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.LISTING,
            msg.sender,
            address(0),
            amount,
            pricePerToken,
            paymentToken,
            listingId
        );
        emit ListingCreated(
            listingId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

function _validateListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) internal view {
        if (amount == 0 || amount > MAX_AMOUNT_PER_LISTING)
            revert InvalidAmount(amount, MAX_AMOUNT_PER_LISTING);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidPrice(pricePerToken, MAX_PRICE_PER_TOKEN);
        if (expirationTime <= block.timestamp)
            revert ListingExpired(0, expirationTime);
        if (!_supportedPaymentTokensSet.contains(paymentToken))
            revert UnsupportedPaymentToken(paymentToken);
        if (
            IERC1155(address(asteroidXToken)).balanceOf(msg.sender, tokenId) <
            amount
        ) revert InsufficientTokenBalance(tokenId, amount);
        if (
            !IERC1155(address(asteroidXToken)).isApprovedForAll(
                msg.sender,
                address(this)
            )
        ) revert MarketplaceNotApproved();
    }

function _transferNFT(
        address from,
        address to,
        uint256 tokenId,
        uint256 amount,
        bool viaVault
    ) internal {
        if (viaVault) {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                address(marketplaceVaultContract),
                tokenId,
                amount,
                ""
            );
            marketplaceVaultContract.transferNFTToBuyer(
                address(asteroidXToken),
                tokenId,
                amount,
                to
            );
        } else {
            IERC1155(address(asteroidXToken)).safeTransferFrom(
                from,
                to,
                tokenId,
                amount,
                ""
            );
        }
    }

