function _handlePaymentWithFees(
        address paymentToken,
        address from,
        address seller,
        uint256 totalAmount,
        uint256 msgValue,
        address feePaymentToken
    ) internal {
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalAmount,
            feePaymentToken
        );
        if (paymentToken == address(0)) {
            if (msgValue < totalAmount)
                revert InsufficientETHSentForPurchase(msgValue, totalAmount);
            if (sellerProceeds > 0) {
                (bool successSeller, ) = payable(seller).call{
                    value: sellerProceeds
                }("");
                if (!successSeller) revert EthTransferFailed(seller);
            }
            if (platformFee > 0) {
                (bool successFee, ) = payable(feeRecipient).call{
                    value: platformFee
                }("");
                if (!successFee) revert EthTransferFailed(feeRecipient);
            }
            if (msgValue > totalAmount) {
                uint256 excessAmount = msgValue - totalAmount;
                (bool successRefund, ) = payable(from).call{
                    value: excessAmount
                }("");
                if (!successRefund) revert EthRefundFailed(from);
            }
        } else {
            if (!_supportedPaymentTokensSet.contains(paymentToken))
                revert UnsupportedPaymentToken(paymentToken);
            if (msgValue != 0) revert UnexpectedETHPayment();
            IERC20 token = IERC20(paymentToken);
            if (token.allowance(from, address(this)) < totalAmount)
                revert InsufficientAllowance(
                    totalAmount,
                    token.allowance(from, address(this)),
                    paymentToken
                );
            if (token.balanceOf(from) < totalAmount)
                revert InsufficientBalance(
                    totalAmount,
                    token.balanceOf(from),
                    paymentToken
                );

            if (sellerProceeds > 0) {
                token.safeTransferFrom(from, seller, sellerProceeds);
            }
            if (platformFee > 0) {
                token.safeTransferFrom(from, feeRecipient, platformFee);
            }
        }
    }

