function proposeFeeRecipientUpdate(address newFeeRecipient)
        external
        onlyOwner
    {
        if (newFeeRecipient == address(0)) revert InvalidRecipient();
        pendingRecipientUpdate = AsteroidXMarketplaceStructs.PendingUpdate({
            value: uint256(uint160(newFeeRecipient)),
            timestamp: block.timestamp
        });
        emit TimelockProposed(
            "RECIPIENT",
            uint256(uint160(newFeeRecipient)),
            block.timestamp
        );
    }

function acceptOffer(uint256 offerId)
        external
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer == msg.sender) revert CannotAcceptOwnOffer();
        if (block.timestamp >= offer.expirationTime)
            revert OfferExpired(offerId, offer.expirationTime);

        IERC1155AsteroidX token = asteroidXToken;
        if (token.balanceOf(msg.sender, offer.tokenId) < offer.amount)
            revert InsufficientTokenBalance(offer.tokenId, offer.amount);

        uint256 totalOfferValue = offer.amount * offer.pricePerToken;
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalOfferValue,
            offer.paymentToken
        );

        _transferNFT(
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            true
        );
        _handleOfferFundWithdrawal(
            offerId,
            offer.paymentToken,
            msg.sender,
            feeRecipient,
            sellerProceeds,
            platformFee
        );
        _deactivateOffer(offerId);
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER,
            msg.sender,
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferAccepted(
            offerId,
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            totalOfferValue,
            block.timestamp,
            offer.paymentToken
        );
    }

