function _recordPriceHistory(
        uint256 relatedId,
        uint256 tokenId,
        uint256 pricePerToken,
        uint256 amount,
        address seller,
        address buyer,
        address paymentToken
    ) internal returns (uint256) {
        uint256 totalValue = pricePerToken * amount;
        AsteroidXMarketplaceStructs.PriceRecord
            memory priceRecord = AsteroidXMarketplaceStructs.PriceRecord({
                listingId: relatedId,
                tokenId: tokenId,
                price: pricePerToken,
                amount: amount,
                totalValue: totalValue,
                timestamp: block.timestamp,
                seller: seller,
                buyer: buyer,
                paymentToken: paymentToken
            });
        uint256 recordIndex = priceHistories.length;
        priceHistories.push(priceRecord);
        tokenPriceHistoryIndexes[tokenId].push(recordIndex);
        emit PriceHistoryRecorded(
            tokenId,
            relatedId,
            pricePerToken,
            amount,
            totalValue,
            block.timestamp,
            seller,
            buyer,
            paymentToken
        );
        return recordIndex;
    }

function _remove(Set storage set, bytes32 value) private returns (bool) {
        // We cache the value's position to prevent multiple reads from the same storage slot
        uint256 position = set._positions[value];

        if (position != 0) {
            // Equivalent to contains(set, value)
            // To delete an element from the _values array in O(1), we swap the element to delete with the last one in
            // the array, and then remove the last element (sometimes called as 'swap and pop').
            // This modifies the order of the array, as noted in {at}.

            uint256 valueIndex = position - 1;
            uint256 lastIndex = set._values.length - 1;

            if (valueIndex != lastIndex) {
                bytes32 lastValue = set._values[lastIndex];

                // Move the lastValue to the index where the value to delete is
                set._values[valueIndex] = lastValue;
                // Update the tracked position of the lastValue (that was just moved)
                set._positions[lastValue] = position;
            }

            // Delete the slot where the moved value was stored
            set._values.pop();

            // Delete the tracked position for the deleted slot
            delete set._positions[value];

            return true;
        } else {
            return false;
        }
    }

function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

function purchaseListing(uint256 listingId, uint256 amount)
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) revert ListingNotActive(listingId);
        if (block.timestamp >= listing.expirationTime)
            revert ListingExpired(listingId, listing.expirationTime);
        if (amount == 0 || amount > listing.amount)
            revert InvalidAmount(amount, listing.amount);
        if (msg.sender == listing.seller) revert CannotBuyOwnListing();

        uint256 totalPrice = amount * listing.pricePerToken;
        listing.amount -= amount;
        if (listing.amount == 0) {
            _deactivateListing(listingId);
        }
        marketplaceVaultContract.transferNFTToBuyer(
            address(asteroidXToken),
            listing.tokenId,
            amount,
            msg.sender
        );
        _handlePaymentWithFees(
            listing.paymentToken,
            msg.sender,
            listing.seller,
            totalPrice,
            msg.value,
            listing.paymentToken
        );
        _recordTransaction(
            listing.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.SALE,
            listing.seller,
            msg.sender,
            amount,
            listing.pricePerToken,
            listing.paymentToken,
            listingId
        );
        emit ListingSold(
            listingId,
            msg.sender,
            listing.tokenId,
            amount,
            totalPrice,
            block.timestamp,
            listing.paymentToken
        );
    }

function _deactivateListing(uint256 listingId) internal {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) return;
        listing.active = false;
        activeListingsByToken[listing.tokenId].remove(listingId);
        activeListingsBySeller[listing.seller].remove(listingId);
    }

function transferNFTToBuyer(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (buyer == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            buyer,
            tokenId,
            amount,
            ""
        );
        emit NFTTransferredToBuyer(tokenContract, tokenId, amount, buyer);
    }

function _handlePaymentWithFees(
        address paymentToken,
        address from,
        address seller,
        uint256 totalAmount,
        uint256 msgValue,
        address feePaymentToken
    ) internal {
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalAmount,
            feePaymentToken
        );
        if (paymentToken == address(0)) {
            if (msgValue < totalAmount)
                revert InsufficientETHSentForPurchase(msgValue, totalAmount);
            if (sellerProceeds > 0) {
                (bool successSeller, ) = payable(seller).call{
                    value: sellerProceeds
                }("");
                if (!successSeller) revert EthTransferFailed(seller);
            }
            if (platformFee > 0) {
                (bool successFee, ) = payable(feeRecipient).call{
                    value: platformFee
                }("");
                if (!successFee) revert EthTransferFailed(feeRecipient);
            }
            if (msgValue > totalAmount) {
                uint256 excessAmount = msgValue - totalAmount;
                (bool successRefund, ) = payable(from).call{
                    value: excessAmount
                }("");
                if (!successRefund) revert EthRefundFailed(from);
            }
        } else {
            if (!_supportedPaymentTokensSet.contains(paymentToken))
                revert UnsupportedPaymentToken(paymentToken);
            if (msgValue != 0) revert UnexpectedETHPayment();
            IERC20 token = IERC20(paymentToken);
            if (token.allowance(from, address(this)) < totalAmount)
                revert InsufficientAllowance(
                    totalAmount,
                    token.allowance(from, address(this)),
                    paymentToken
                );
            if (token.balanceOf(from) < totalAmount)
                revert InsufficientBalance(
                    totalAmount,
                    token.balanceOf(from),
                    paymentToken
                );

            if (sellerProceeds > 0) {
                token.safeTransferFrom(from, seller, sellerProceeds);
            }
            if (platformFee > 0) {
                token.safeTransferFrom(from, feeRecipient, platformFee);
            }
        }
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

